        // to one cell is repaired while the client remains in the room.
        internal void OnClientTerrainCellApplicationFailed(Point3 cell, long sequence)
        {
            if (IsHost || sequence <= 0 || GameManager.Project == null)
                return;
            Point2 coordinates = Terrain.ToChunk(cell.X, cell.Z);
            if (!m_clientTerrainChunkVerifications.TryGetValue(coordinates,
                    out PendingTerrainChunkVerification pending))
            {
                pending = new PendingTerrainChunkVerification();
                m_clientTerrainChunkVerifications.Add(coordinates, pending);
            }
            pending.RequiredRevision = Math.Max(pending.RequiredRevision, sequence);
            pending.DueTime = Time.RealTime + TerrainChunkVerificationDelay;
        }

        private void TrackHostTerrainPlaceIntent(ComponentPlayer player, Ray3? interactRay)
        {
            if (player == null || !interactRay.HasValue || client?.IsConnected != true ||
                GetConnectedRemoteClients().Count == 0 ||
                !TryGetTerrainPlacePrediction(player, interactRay.Value, out Point3 cell,
                    out int expectedValue, out _))
                return;
            m_hostTerrainPlaceFallbacks[cell] = new PendingHostTerrainPlaceFallback
            {
                ExpectedValue = expectedValue,
                CheckAfterFrameIndex = Time.FrameIndex + 1,
                ExpiresAt = Time.RealTime + HostTerrainPlaceFallbackLifetime
            };
        }

        // Source: Survivalcraft/Game/SubsystemTerrain.cs:SubsystemTerrain.ChangeCell
        private GameModifiedCellsMessage FilterPendingTerrainPlacePredictions(
            GameModifiedCellsMessage message)
        {
            if (message?.ModifiedCells == null || message.CellValues == null ||
                (m_pendingTerrainPlacePredictionCells.Count == 0 &&
                m_localCollapsingPlacePredictions.Count == 0))
                return message;

            var cells = new Dictionary<Point3, bool>();
            var values = new List<int>();
            int index = 0;
            foreach (KeyValuePair<Point3, bool> item in message.ModifiedCells)
            {
                int value = index < message.CellValues.Count
                    ? message.CellValues[index]
                    : 0;
                bool collapsingPrediction = m_localCollapsingPlacePredictions.TryGetValue(
                    item.Key, out double expiresAt) && Time.RealTime <= expiresAt;
                bool conflictsWithPrediction = m_pendingTerrainPlacePredictionCells.TryGetValue(
                    item.Key, out int requestId) &&
                    m_pendingTerrainPlacePredictions.TryGetValue(requestId,
                        out PendingTerrainPlacePrediction prediction) &&
                    prediction.HasLocalPrediction && value != prediction.LocalPredictedValue &&
                    value == prediction.Request.ExpectedValue;
                if (!collapsingPrediction && !conflictsWithPrediction)
                {
                    cells[item.Key] = item.Value;
                    values.Add(value);
                }
                index++;
            }
            if (cells.Count == message.ModifiedCells.Count) return message;
            return new GameModifiedCellsMessage(cells, values, message.Tick,
                message.IsCatchUp, message.TargetClientId, message.Sequence);
        }

        private void SendAuthoritativeTerrainRepair(int targetClientId,
            Dictionary<Point3, bool> requestedCells)
        {
            if (!IsHost || targetClientId <= 0 || requestedCells == null ||
                requestedCells.Count == 0 || !m_networkPlayerData.ContainsKey(targetClientId))
                return;
            SubsystemTerrain terrain = GameManager.Project?.FindSubsystem<SubsystemTerrain>(false);
            if (terrain == null) return;
            var cells = new List<KeyValuePair<Point3, bool>>();
            foreach (KeyValuePair<Point3, bool> item in requestedCells)
            {
                if (!terrain.Terrain.IsCellValid(item.Key.X, item.Key.Y, item.Key.Z)) continue;
                cells.Add(item);
            }
            if (cells.Count == 0) return;
            for (int offset = 0; offset < cells.Count; offset += TerrainReliableBatchSize)
            {
                var batch = new Dictionary<Point3, bool>();
                var values = new List<int>();
                int count = Math.Min(TerrainReliableBatchSize, cells.Count - offset);
                for (int i = 0; i < count; i++)
                {
                    KeyValuePair<Point3, bool> item = cells[offset + i];
                    batch[item.Key] = item.Value;
                    int value = terrain.Terrain.GetCellValue(
                        item.Key.X, item.Key.Y, item.Key.Z);
                    values.Add(Terrain.ReplaceLight(value, 0));
                }
                var response = new GameModifiedCellsMessage(batch, values, client.Step,
                    true, targetClientId);
                // Source: Mod/Comms/Comms.Drt/Func/Server/Set/ServerGame.cs:
                // ServerGame.SendDirectInput
                // Per-cell tick rejection makes this reliable response order-independent.
                client.SendDirectInput(targetClientId,
                    Message.WriteWithSender(response, client.Address));
            }
        }

        private GameModifiedCellsMessage FilterStaleTerrainRepairs(
            GameModifiedCellsMessage message)
        {
            if (message?.IsCatchUp != true || message.ModifiedCells == null ||
                message.CellValues == null || m_pendingTerrainPredictionCells.Count == 0)
                return message;

            var cells = new Dictionary<Point3, bool>();
            var values = new List<int>();
            int index = 0;
            foreach (KeyValuePair<Point3, bool> item in message.ModifiedCells)
            {
                int value = index < message.CellValues.Count
                    ? message.CellValues[index]
                    : 0;
                bool staleRepair = m_pendingTerrainPredictionCells.TryGetValue(
                    item.Key, out int requestId) &&
                    m_pendingTerrainPredictions.TryGetValue(
                        requestId, out PendingTerrainPrediction prediction) &&
                    value != prediction.Request.PredictedValue;
                if (!staleRepair)
                {
                    cells[item.Key] = item.Value;
                    values.Add(value);
                }
                index++;
            }
            if (cells.Count == message.ModifiedCells.Count) return message;
            return cells.Count > 0
                ? new GameModifiedCellsMessage(cells, values, message.Tick,
                    message.IsCatchUp, message.TargetClientId, message.Sequence)
                : null;
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Dig
        private void HandleTerrainDigRequest(TerrainDigRequestMessage message, int sourceClientId)
        {
            if (!IsHost || message == null || sourceClientId <= 0) return;
            long requestKey = ((long)sourceClientId << 32) | (uint)message.RequestId;
            if (m_processedTerrainDigRequests.TryGetValue(requestKey,
                out TerrainDigResultMessage previousResult))
            {
                NetworkMessageSender.SendTerrainDigResult(sourceClientId, previousResult);
                return;
            }

            Project project = GameManager.Project;
            bool accepted = false;
            int authoritativeValue = 0;
            if (project != null && m_networkPlayerData.TryGetValue(sourceClientId,
                out PlayerData playerData) && playerData?.ComponentPlayer != null)
            {
                ComponentPlayer player = playerData.ComponentPlayer;
                ComponentMiner miner = player.ComponentMiner;
                SubsystemTerrain terrain = project.FindSubsystem<SubsystemTerrain>(true);
                int currentCellValue = terrain.Terrain.GetCellValue(
                    message.Cell.X, message.Cell.Y, message.Cell.Z);
                authoritativeValue = Terrain.ReplaceLight(currentCellValue, 0);
                Vector3 center = new Vector3(message.Cell.X + 0.5f,
                    message.Cell.Y + 0.5f, message.Cell.Z + 0.5f);
                if (authoritativeValue == message.PredictedValue)
                {
                    accepted = true;
                }
                else if (miner != null &&
                    authoritativeValue == message.ExpectedValue)
                {
                    SubsystemGameInfo gameInfo =
                        project.FindSubsystem<SubsystemGameInfo>(true);
                    bool creative = gameInfo.WorldSettings.GameMode == GameMode.Creative;
                    float reach = creative ? SettingsManager.CreativeReach : 5f;
                    // Source: ComponentMiner.Dig
                    // The sampled client position is only a reach check. Never rewind the host
                    // replica body to the historical position captured with this request.
                    Vector3 authoritativePlayerPosition = player.ComponentBody.Position;
                    if (m_networkPlayerInputs.TryGetValue(sourceClientId,
                        out NetworkPlayerInputState inputState) &&
                        Time.RealTime - inputState.LastReceivedTime <= RemoteInputHoldDuration)
                    {
                        authoritativePlayerPosition = inputState.BodyPosition;
                    }
                    bool inReach = Vector3.DistanceSquared(
                        authoritativePlayerPosition, center) <=
                        MathUtils.Sqr(reach + 1.5f);
                    Vector3 rayDirection = message.DigRay.Direction;
                    TerrainRaycastResult? targetRaycast = null;
                    if (inReach && message.HitFace >= 0 && message.HitFace <= 5 &&
                        rayDirection.LengthSquared() > 0.0001f)
                    {
                        // Source: SubsystemTerrain.cs:SubsystemTerrain.Raycast
                        // Test the client's requested cell directly. A preceding predicted cell may
                        // still exist on the host while fast consecutive dig requests are in flight.
                        rayDirection = Vector3.Normalize(rayDirection);
                        var ray = new Ray3(message.DigRay.Position, rayDirection);
                        Block targetBlock = BlocksManager.Blocks[
                            Terrain.ExtractContents(currentCellValue)];
                        var localRay = new Ray3(ray.Position - new Vector3(
                            message.Cell.X, message.Cell.Y, message.Cell.Z), ray.Direction);
                        float? distance = targetBlock.Raycast(localRay, terrain,
                            currentCellValue, true, out int collisionBoxIndex,
                            out BoundingBox collisionBox);
                        if (!targetBlock.IsDiggingTransparent && distance.HasValue &&
                            distance.Value >= 0f && distance.Value <= 15f)
                        {
                            targetRaycast = new TerrainRaycastResult
                            {
                                Ray = ray,
                                Value = currentCellValue,
                                CellFace = new CellFace(message.Cell.X, message.Cell.Y,
                                    message.Cell.Z, message.HitFace),
                                CollisionBoxIndex = collisionBoxIndex,
                                Distance = distance.Value
                            };
                        }
                    }
                    if (targetRaycast.HasValue)
                    {
                        IInventory inventory = miner.Inventory;
                        bool validToolSlot = ApplyTerrainDigToolState(inventory, message);
                        int toolValue = validToolSlot ? miner.ActiveBlockValue : 0;
                        int toolContents = Terrain.ExtractContents(toolValue);
                        Block block = BlocksManager.Blocks[Terrain.ExtractContents(authoritativeValue)];
                        Block tool = BlocksManager.Blocks[toolContents];
                        bool levelSufficient = ModManager.ModParentMethod.InvokeParentMethod<bool>(
                            miner, "IsLevelSufficientForTool", toolValue);
                        float requiredTime = ModManager.ModParentMethod.InvokeParentMethod<float>(
                            miner, "CalculateDigTime", authoritativeValue, toolContents);
                        float elapsedTime = MathUtils.Max(0f,
                            (message.CompletedClientTick - message.StartClientTick) * ServerTickDuration);
                        BlockPlacementData digValue = block.GetDigValue(
                            terrain, miner, currentCellValue, toolValue, targetRaycast.Value);
                        Point3 digPoint = new Point3(digValue.CellFace.X,
                            digValue.CellFace.Y, digValue.CellFace.Z);
                        bool matchingDigProgress = miner.DigCellFace.HasValue &&
                            miner.DigCellFace.Value.X == message.Cell.X &&
                            miner.DigCellFace.Value.Y == message.Cell.Y &&
                            miner.DigCellFace.Value.Z == message.Cell.Z &&
                            miner.DigProgress >= 0.85f;
                        if (validToolSlot && levelSufficient && digPoint == message.Cell &&
                            (creative || matchingDigProgress ||
                                elapsedTime + 0.4f >= requiredTime))
                        {
                            terrain.DestroyCell(tool.ToolLevel, digPoint.X, digPoint.Y,
                                digPoint.Z, digValue.Value, false, false);
                            terrain.TerrainUpdater.RequestSynchronousUpdate();
                            miner.DamageActiveTool(1);
                            if (miner.ComponentCreature.PlayerStats != null)
                                miner.ComponentCreature.PlayerStats.BlocksDug++;
                            authoritativeValue = Terrain.ReplaceLight(
                                terrain.Terrain.GetCellValue(digPoint.X, digPoint.Y, digPoint.Z), 0);
                            accepted = true;
                        }
                    }
                }
            }

            var result = new TerrainDigResultMessage(message.RequestId, message.Cell,
                accepted, authoritativeValue, client.Step);
            if (accepted)
            {
                if (m_processedTerrainDigRequests.Count >= 2048)
                    m_processedTerrainDigRequests.Clear();
                m_processedTerrainDigRequests[requestKey] = result;
                PublishServerAudit("terrain.dig", sourceClientId,
                    "cell=" + message.Cell.X.ToString(CultureInfo.InvariantCulture) + "," +
                    message.Cell.Y.ToString(CultureInfo.InvariantCulture) + "," +
                    message.Cell.Z.ToString(CultureInfo.InvariantCulture));
            }
            NetworkMessageSender.SendTerrainDigResult(sourceClientId, result);
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Dig
        // Source: Survivalcraft/Game/ComponentInventoryBase.cs:ComponentInventoryBase.AddSlotItems
        private static bool ApplyTerrainDigToolState(IInventory inventory,
            TerrainDigRequestMessage message)
        {
            if (inventory == null || message == null || message.ActiveSlotIndex < 0 ||
                message.ActiveSlotIndex >= inventory.VisibleSlotsCount ||
                message.ToolCount < 0 || (message.ToolValue != 0 && message.ToolCount <= 0))
                return false;
            int slot = message.ActiveSlotIndex;
            int count = message.ToolValue == 0 ? 0 : Math.Min(message.ToolCount,
                inventory.GetSlotCapacity(slot, message.ToolValue));
            if (message.ToolValue != 0 && count <= 0) return false;
            inventory.ActiveSlotIndex = slot;
            inventory.RemoveSlotItems(slot, int.MaxValue);
            if (count > 0) inventory.AddSlotItems(slot, message.ToolValue, count);
            return inventory.GetSlotValue(slot) == message.ToolValue &&
                inventory.GetSlotCount(slot) == count;
        }

        private void ConfirmTerrainPredictions(GameModifiedCellsMessage message)
        {
            if (message?.ModifiedCells == null || message.CellValues == null) return;
            int index = 0;
            foreach (Point3 cell in message.ModifiedCells.Keys)
            {
                if (index >= message.CellValues.Count) break;
                if (m_pendingTerrainPredictionCells.TryGetValue(cell, out int requestId) &&
                    m_pendingTerrainPredictions.TryGetValue(requestId,
                        out PendingTerrainPrediction prediction) &&
                    message.CellValues[index] == prediction.Request.PredictedValue)
                    RemovePendingTerrainPrediction(requestId);
                m_localTerrainUsePredictions.Remove(cell);
                index++;
            }
        }

        private void RecordHostTerrainChanges(GameModifiedCellsMessage message,
            int authoritativeTick, bool isFluidSettlementConfirmation = false)
        {
            if (message?.ModifiedCells == null) return;
            lock (m_terrainJournalLock)
            {
                int index = 0;
                foreach (KeyValuePair<Point3, bool> item in message.ModifiedCells)
                {
                    if (message.CellValues != null && index < message.CellValues.Count)
                    {
                        m_pendingTerrainChanges[item.Key] = new TerrainCellState
                        {
                            IsModified = item.Value,
                            CellValue = message.CellValues[index],
                            Tick = authoritativeTick,
                            Sequence = message.Sequence
                        };
                        if (message.Sequence > 0)
                        {
                            Point2 coordinates = Terrain.ToChunk(item.Key.X, item.Key.Z);
                            m_hostTerrainChunkRevisions[coordinates] = message.Sequence;
                        }
                        int cellValue = message.CellValues[index];
                        if (!isFluidSettlementConfirmation &&
                            Terrain.ExtractContents(cellValue) == 0 &&
                            TryGetFluidSettlementDelay(item.Key, out double delay))
                        {
                            double dueGameTime = GetCurrentGameTime() + delay;
                            if (m_pendingFluidSettlements.TryGetValue(item.Key,
                                out PendingFluidSettlement pending))
                            {
                                pending.TransientValue = cellValue;
                                pending.DueGameTime = Math.Min(
                                    pending.DueGameTime, dueGameTime);
                            }
                            else
                            {
                                m_pendingFluidSettlements[item.Key] =
                                    new PendingFluidSettlement
                                    {
                                        TransientValue = cellValue,
                                        DueGameTime = dueGameTime
                                    };
                            }
                        }
                        else
                        {
                            m_pendingFluidSettlements.Remove(item.Key);
                        }
                    }
                    index++;
                }
            }
        }

        // Source: Survivalcraft/Game/SubsystemFluidBlockBehavior.cs:
        // SubsystemFluidBlockBehavior.SpreadFluid
        // Fluid changes call ProcessModifiedCells internally, before SuSubsystemTerrain can
        // journal them. Confirm only transient air cells beside fluid after the native spread
        // interval, then reuse one terrain read for comparison, broadcast and persistence.
        private void ConfirmPendingFluidSettlements()
        {
            if (!IsHost || m_pendingFluidSettlements.Count == 0) return;
            double gameTime = GetCurrentGameTime();
            Point3[] dueCells;
            lock (m_terrainJournalLock)
            {
                dueCells = m_pendingFluidSettlements.Where(item =>
                    gameTime >= item.Value.DueGameTime).Select(item => item.Key).ToArray();
            }
            if (dueCells.Length == 0) return;

            SubsystemTerrain terrain = GameManager.Project?
                .FindSubsystem<SubsystemTerrain>(false);
            if (terrain == null) return;
            var settledCells = new List<KeyValuePair<Point3, int>>();
            foreach (Point3 cell in dueCells)
            {
                PendingFluidSettlement pending;
                lock (m_terrainJournalLock)
                {
                    if (!m_pendingFluidSettlements.TryGetValue(cell, out pending) ||
                        gameTime < pending.DueGameTime)
                        continue;
                    m_pendingFluidSettlements.Remove(cell);
                }

                int finalValue = Terrain.ReplaceLight(terrain.Terrain.GetCellValue(
                    cell.X, cell.Y, cell.Z), 0);
                settledCells.Add(new KeyValuePair<Point3, int>(cell, finalValue));
            }

            // Source: ScMultiplayer.PublishTerrainChanges
            // A fluid wave can settle many cells at once. Keep the existing 48-cell reliable
            // payload limit, but allocate one sequence per batch instead of one per cell.
            for (int offset = 0; offset < settledCells.Count;
                offset += TerrainReliableBatchSize)
            {
                int count = Math.Min(TerrainReliableBatchSize, settledCells.Count - offset);
                var cells = new Dictionary<Point3, bool>();
                var values = new List<int>(count);
                for (int i = 0; i < count; i++)
                {
                    KeyValuePair<Point3, int> item = settledCells[offset + i];
                    cells[item.Key] = true;
                    values.Add(item.Value);
                }
                var confirmation = new GameModifiedCellsMessage(cells, values,
                    client.Step, false, -1);
                lock (m_terrainJournalLock)
                    confirmation.Sequence = ++m_hostTerrainSequence;
                RecordHostTerrainChanges(confirmation, client.Step,
                    isFluidSettlementConfirmation: true);
                RecordHostTerrainJournal(confirmation);
                NetworkMessageSender.SendScheduledMessage(-1, confirmation);
            }
        }

        // Source: Survivalcraft/Game/SubsystemWaterBlockBehavior.cs:
        // SubsystemWaterBlockBehavior.Update
        private bool TryGetFluidSettlementDelay(Point3 cell, out double delay)
        {
            delay = 0.0;
            SubsystemTerrain terrain = GameManager.Project?
                .FindSubsystem<SubsystemTerrain>(false);
            if (terrain == null) return false;
            bool slowFluidFound = false;
            for (int face = 0; face < 6; face++)
            {
                Point3 offset = CellFace.FaceToPoint3(face);
                int value = terrain.Terrain.GetCellValue(
                    cell.X + offset.X, cell.Y + offset.Y, cell.Z + offset.Z);
                Block block = BlocksManager.Blocks[Terrain.ExtractContents(value)];
                if (block is WaterBlock)
                {
                    delay = WaterSettlementDelay;
                    return true;
                }
                if (block is FluidBlock)
                    slowFluidFound = true;
            }
            if (slowFluidFound)
                delay = SlowFluidSettlementDelay;
            return slowFluidFound;
        }

        private static double GetCurrentGameTime()
        {
            return GameManager.Project?.FindSubsystem<SubsystemTime>(false)?.GameTime ?? 0.0;
        }

        private void MergePendingTerrainChanges()
        {
            lock (m_terrainJournalLock)
                MergePendingTerrainChangesLocked();
        }

        private void MergePendingTerrainChangesLocked()
        {
            foreach (KeyValuePair<Point3, TerrainCellState> item in m_pendingTerrainChanges)
            {
                m_terrainCheckpoint[item.Key] = item.Value;
                Point2 coordinates = Terrain.ToChunk(item.Key.X, item.Key.Z);
                if (!m_terrainCheckpointByChunk.TryGetValue(coordinates,
                        out Dictionary<Point3, TerrainCellState> chunkCheckpoint))
                {
                    chunkCheckpoint = new Dictionary<Point3, TerrainCellState>();
                    m_terrainCheckpointByChunk.Add(coordinates, chunkCheckpoint);
                }
                chunkCheckpoint[item.Key] = item.Value;
            }
            m_pendingTerrainChanges.Clear();
        }

        // Source: Comms/Drt/Client.cs:Client.GameJoined
        // The base world is the room-creation snapshot. This targeted checkpoint advances a
        // rejoining client from that snapshot to the host's current authoritative terrain tick.
        private void SendTerrainCatchUp(int targetClientId, int snapshotStartTick)
        {
            List<KeyValuePair<Point3, TerrainCellState>> snapshot;
            int targetTick = client.Step;
            long headSequence;
            lock (m_terrainJournalLock)
            {
                headSequence = m_hostTerrainSequence;
                MergePendingTerrainChangesLocked();
                // Source: ScMultiplayer.AcceptNetworkPlayerJoin
                // The live world archive already contains terrain through the join start tick.
                // Only cells changed while that archive was transferred need a final checkpoint.
                snapshot = m_terrainCheckpoint
                    .Where(item => item.Value.Tick > snapshotStartTick)
                    .OrderBy(item => item.Value.Tick)
                    .ThenBy(item => item.Key.X)
                    .ThenBy(item => item.Key.Y)
                    .ThenBy(item => item.Key.Z)
                    .ToList();
            }

            if (snapshot.Count == 0)
            {
                var marker = new GameModifiedCellsMessage(
                    new Dictionary<Point3, bool>(), new List<int>(), targetTick, true, targetClientId);
                marker.HeadSequence = headSequence;
                QueueJoinCatchUpPayload(targetClientId,
                    Message.WriteWithSender(marker, client.Address));
                return;
            }

            for (int offset = 0; offset < snapshot.Count; offset += TerrainCatchUpBatchSize)
            {
                var cells = new Dictionary<Point3, bool>();
                var values = new List<int>();
                int count = Math.Min(TerrainCatchUpBatchSize, snapshot.Count - offset);
                for (int i = 0; i < count; i++)
                {
                    KeyValuePair<Point3, TerrainCellState> item = snapshot[offset + i];
                    cells[item.Key] = item.Value.IsModified;
                    values.Add(item.Value.CellValue);
                }
                var message = new GameModifiedCellsMessage(
                    cells, values, targetTick, true, targetClientId);
                message.HeadSequence = headSequence;
                QueueJoinCatchUpPayload(targetClientId,
                    Message.WriteWithSender(message, client.Address));
            }
            Log.Information($"[ScMP] Sent terrain catch-up: ClientID={targetClientId}, " +
                $"Tick={targetTick}, StartTick={snapshotStartTick}, Cells={snapshot.Count}");
        }

        private IncomingWorldTransfer GetOrCreateIncomingWorldTransfer(
            int transferId, int targetClientId, int chunkCount, int totalLength)
        {
            int expectedChunks = totalLength > 0
                ? (totalLength + WorldTransferChunkSize - 1) / WorldTransferChunkSize
                : 0;
            if (transferId <= 0 || targetClientId != client.ClientID ||
                totalLength <= 0 || totalLength > MaximumWorldTransferSize ||
                chunkCount <= 0 || chunkCount != expectedChunks)
                return null;
            if (m_incomingWorldTransfers.TryGetValue(transferId,
                out IncomingWorldTransfer existing))
            {
                return existing.TargetClientId == targetClientId &&
                    existing.TotalLength == totalLength && existing.Chunks.Length == chunkCount
                    ? existing
                    : null;
            }
            var transfer = new IncomingWorldTransfer
            {
                TransferId = transferId,
                TargetClientId = targetClientId,
                TotalLength = totalLength,
                Chunks = new byte[chunkCount][],
                StartTime = Time.RealTime,
                LastProgressTime = Time.RealTime
            };
            m_incomingWorldTransfers.Add(transferId, transfer);
            return transfer;
        }

        private void HandleGamePakWorldChunkMessage(GamePakWorldChunkMessage message)
        {
            if (IsHost || message == null) return;
            IncomingWorldTransfer transfer = GetOrCreateIncomingWorldTransfer(
                message.TransferId, message.TargetClientId,
                message.ChunkCount, message.TotalLength);
            if (transfer == null || message.ChunkIndex < 0 ||
                message.ChunkIndex >= transfer.Chunks.Length || message.Data == null)
                return;
            int expectedLength = Math.Min(WorldTransferChunkSize,
                transfer.TotalLength - message.ChunkIndex * WorldTransferChunkSize);
            if (message.Data.Length != expectedLength) return;
            if (transfer.Chunks[message.ChunkIndex] == null)
            {
                transfer.Chunks[message.ChunkIndex] = message.Data;
                transfer.ReceivedChunkCount++;
                transfer.ReceivedBytes += message.Data.Length;
                transfer.HighestReceivedChunkIndex = Math.Max(
                    transfer.HighestReceivedChunkIndex, message.ChunkIndex);
                while (transfer.HighestContiguousChunkIndex + 1 < transfer.Chunks.Length &&
                    transfer.Chunks[transfer.HighestContiguousChunkIndex + 1] != null)
                    transfer.HighestContiguousChunkIndex++;
                transfer.LastProgressTime = Time.RealTime;
                RecordClientJoinProgress();
            }
            TryCompleteIncomingWorldTransfer(transfer);
        }

        private void TryCompleteIncomingWorldTransfer(IncomingWorldTransfer transfer)
        {
            if (transfer?.Manifest == null ||
                transfer.ReceivedChunkCount != transfer.Chunks.Length)
                return;
            var worldData = new byte[transfer.TotalLength];
            int offset = 0;
            foreach (byte[] chunk in transfer.Chunks)
            {
                if (chunk == null || offset + chunk.Length > worldData.Length) return;
                Array.Copy(chunk, 0, worldData, offset, chunk.Length);
                offset += chunk.Length;
            }
            if (offset != worldData.Length) return;
            GamePakWorldMessage manifest = transfer.Manifest;
            byte[] expectedHash = manifest.WorldSha256;
            byte[] actualHash = SHA256.HashData(worldData);
            if (expectedHash == null || expectedHash.Length != actualHash.Length ||
                !CryptographicOperations.FixedTimeEquals(expectedHash, actualHash))
            {
                ResetIncomingWorldTransferAfterChecksumFailure(transfer);
                return;
            }
            double elapsed = Math.Max(Time.RealTime - transfer.StartTime, 0.0);
            Log.Information($"[ScMP] World download complete: Transfer={transfer.TransferId}, " +
                $"Transport=UDP, Bytes={transfer.TotalLength}, Seconds={elapsed:0.00}, " +
                $"RepairRounds={transfer.RepairRequestCount}");
            if (m_joinRoomBusyDialog != null)
                m_joinRoomBusyDialog.SmallMessage =
                    "Connected.\r\nWorld download complete.\r\nImporting world...";
            m_joinAwaitingWorldProgress = false;
            manifest.WorldData = worldData;
            manifest.ChunkCount = 0;
            m_incomingWorldTransfers.Remove(transfer.TransferId);
            HandleGamePakWorldMessage(manifest);
        }

        // Source: ScMultiplayer.cs:RequestMissingWorldTransferChunks
        private static void ResetIncomingWorldTransferAfterChecksumFailure(
            IncomingWorldTransfer transfer)
        {
            Array.Clear(transfer.Chunks, 0, transfer.Chunks.Length);
            transfer.ReceivedChunkCount = 0;
            transfer.ReceivedBytes = 0;
            transfer.HighestContiguousChunkIndex = -1;
            transfer.HighestReceivedChunkIndex = -1;
            transfer.LastProgressTime = Time.RealTime;
            transfer.LastStatusRequestTime = 0.0;
            transfer.LastRepairRequestTime = 0.0;
            transfer.RepairRequestCount++;
            Log.Warning($"[ScMP] World transfer checksum failed; requesting all chunks again: " +
                $"Transfer={transfer.TransferId}, Attempt={transfer.RepairRequestCount}");
        }

        private void HandleGamePakWorldReadyMessage(
            GamePakWorldReadyMessage message, int sourceClientId)
        {
            if (message == null)
                return;

            if (!IsHost)
            {
                if (sourceClientId != 0 || m_pendingWorldReadyTransferId <= 0 ||
                    message.TransferId != m_pendingWorldReadyTransferId)
                    return;
                if (message.Stage == GamePakWorldReadyStage.CatchUpBatchComplete)
                {
                    RecordClientJoinProgress();
                    if (m_clientJoinReadyStage == GamePakWorldReadyStage.CatchUpBatchApplied)
                    {
                        SendClientJoinReadyStage(GamePakWorldReadyStage.CatchUpBatchApplied);
                        return;
                    }
                    // Source: ScMultiplayer.cs:ScMultiplayer.ProcessEndOfFrameActions
                    // The ready marker uses the priority control queue. Put its acknowledgement
                    // behind all preceding gameplay actions so Applied means actually applied.
                    int clientTransferId = message.TransferId;
                    QueueEndOfFrameAction(() =>
                    {
                        if (m_pendingWorldReadyTransferId == clientTransferId)
                        {
                            // Source: CircuitSynchronizer.TryFinalizeSnapshot
                            // Do not tell the host that catch-up is applied until the downloaded
                            // Project has also consumed its first authoritative circuit snapshot.
                            if (m_pendingCircuitReadyTransferId != clientTransferId)
                            {
                                m_circuitSynchronizer?.BeginJoinBootstrap();
                                m_pendingCircuitReadyTransferId = clientTransferId;
                            }
                            TryAcknowledgeClientCatchUpApplied();
                        }
                    });
                    return;
                }
                if (message.Stage != GamePakWorldReadyStage.ReadyToPlay) return;
                int readyTransferId = message.TransferId;
                QueueEndOfFrameAction(() => CompleteClientJoinAfterApply(readyTransferId));
                return;
            }

            if (sourceClientId <= 0)
                return;
            if (!m_worldTransfersAwaitingReady.TryGetValue(sourceClientId,
                    out int transferId) || transferId != message.TransferId)
            {
                // Source: ScMultiplayer.CompleteJoiningClient
                // ReadyToPlay can be lost after the host has removed the active catch-up journal.
                // A retry of the client's last stage must recover that final acknowledgement.
                if (m_completedWorldReadyTransfers.TryGetValue(sourceClientId,
                        out int completedTransferId) &&
                    completedTransferId == message.TransferId &&
                    (message.Stage == GamePakWorldReadyStage.ProjectReady ||
                    message.Stage == GamePakWorldReadyStage.CatchUpBatchApplied))
                {
                    NetworkMessageSender.SendPakWorldReady(sourceClientId,
                        new GamePakWorldReadyMessage(message.TransferId,
                            GamePakWorldReadyStage.ReadyToPlay));
                }
                return;
            }
            switch (message.Stage)
            {
                case GamePakWorldReadyStage.LoadingProject:
                    if (!m_pendingAcceptedJoinKeys.TryGetValue(sourceClientId,
                            out string recordKey) ||
                        !m_playerRecords.TryGetValue(recordKey, out NetworkPlayerRecord record))
                    {
                        AbortJoiningClient(sourceClientId,
                            "The approved player profile is unavailable.");
                        return;
                    }
                    CreateNetworkPlayer(sourceClientId, record.Name, recordKey);
                    if (!m_networkPlayerData.ContainsKey(sourceClientId))
                    {
                        AbortJoiningClient(sourceClientId,
                            "The host could not create the network player.");
                        return;
                    }
                    m_pendingAcceptedJoinKeys.Remove(sourceClientId);
                    SynchronizePlayerProfiles();
                    Log.Information($"[ScMP] Client entered Loading Project: ClientID={sourceClientId}, " +
                        $"Transfer={transferId}");
                    break;

                case GamePakWorldReadyStage.ProjectReady:
                    if (!m_networkPlayerData.ContainsKey(sourceClientId))
                    {
                        AbortJoiningClient(sourceClientId,
                            "The network player was not initialized.");
                        return;
                    }
                    if (m_hostProjectReadyTransfers.TryGetValue(sourceClientId,
                            out int readyTransferId) && readyTransferId == transferId)
                    {
                        NetworkMessageSender.SendPakWorldReady(sourceClientId,
                            new GamePakWorldReadyMessage(transferId,
                                GamePakWorldReadyStage.CatchUpBatchComplete));
                        return;
                    }
                    m_hostProjectReadyTransfers[sourceClientId] = transferId;
                    m_outgoingWorldTransfers.Remove(sourceClientId);
                    SealAndSendJoinCatchUp(sourceClientId, transferId);
                    break;

                case GamePakWorldReadyStage.CatchUpBatchApplied:
                    if (!m_networkPlayerData.ContainsKey(sourceClientId))
                    {
                        AbortJoiningClient(sourceClientId,
                            "The network player was lost during join catch-up.");
                        return;
                    }
                    if (!m_joinCatchUpJournals.TryGetValue(sourceClientId,
                            out JoinCatchUpJournal journal))
                        return;
                    CompleteJoiningClient(sourceClientId, transferId, journal);
                    break;
            }
        }

        // Source: ScMultiplayer.cs:ScMultiplayer.HandleGamePakWorldReadyMessage
        private void CompleteClientJoinAfterApply(int transferId)
        {
            if (m_pendingWorldReadyTransferId != transferId) return;
            Log.Information($"[ScMP] Client catch-up complete: Transfer={transferId}");
            // Source: ScMultiplayer.SendTerrainCatchUp
            // The downloaded archive plus applied catch-up already contains terrain through this
            // head. Use it as the per-chunk baseline instead of requesting every visible chunk
            // again from revision zero.
            m_clientTerrainChunkBaselineRevision = Math.Max(
                m_clientTerrainChunkBaselineRevision,
                m_clientTerrainJoinBaselineRevision);
            m_clientTerrainJoinBaselineRevision = 0L;
            m_pendingWorldReadyTransferId = 0;
            m_pendingCircuitReadyTransferId = 0;
            m_projectReadySentProject = null;
            m_projectReadySentTransferId = 0;
            m_nextClientJoinReadyRetryTime = 0.0;
            m_lastClientJoinBarrierProgressTime = 0.0;
            m_isLoadingDownloadedWorld = false;
            // A fresh world transfer supersedes any lifecycle recovery state left by the
            // previous project. Never carry the input lock into the newly joined world.
            m_clientTerrainRecoveryActive = false;
            m_clientTerrainRecoveryPending = false;
            m_clientTerrainRecoveryRequestInFlight = false;
            m_clientTerrainRecoveryTarget = -1;
            m_clientTerrainRecoveryAcknowledged = -1;
            m_clientTerrainRecoveryReady = -1;
            m_clientTerrainGapDetectedTime = 0.0;
            m_clientWorldRefreshProject = null;
            HideJoinRoomBusyDialog();
        }

        // Source: Mod/Comms/Comms/Peer.cs:Peer.DisconnectPeer
        private void AbortJoiningClient(int sourceClientId, string reason)
        {
            SetServerClientGameTrafficEnabled(sourceClientId, enabled: true);
            m_pendingNetworkPlayers.Remove(sourceClientId);
            m_pendingNetworkPlayerIdentities.Remove(sourceClientId);
            RemoveNetworkPlayer(sourceClientId);
            playerMappingManager.ReleasePlayerIndex(sourceClientId);
            ServerGame game = server?.Games.FirstOrDefault(item => item.GameID == client?.GameID);
            ServerClient remoteClient = game?.Clients.FirstOrDefault(item =>
                item.ClientID == sourceClientId);
            if (remoteClient != null) DisconnectNetworkClient(remoteClient);
            Log.Error($"[ScMP] Aborted joining ClientID {sourceClientId}: {reason}");
        }

        // Source: ScMultiplayer.cs:ScMultiplayer.RecordJoinCatchUpMessage
        private void SealAndSendJoinCatchUp(int targetClientId, int transferId)
        {
            if (!m_joinCatchUpJournals.TryGetValue(targetClientId,
                    out JoinCatchUpJournal journal))
                return;
            // Source: ScMultiplayer.cs:ScMultiplayer.SendTerrainCatchUp
            // Seal one fixed cutoff. Replay older events first, then send the current terrain
            // checkpoint, so historical terrain messages cannot overwrite the authoritative state.
            journal.CutoffSealed = true;
            FlushJoinCatchUpJournal(targetClientId);
            SendTerrainCatchUp(targetClientId, journal.StartTick);
            GetOrCreatePendingJoinCatchUp(targetClientId).CompletionAction = () =>
                NetworkMessageSender.SendPakWorldReady(targetClientId,
                    new GamePakWorldReadyMessage(transferId,
                        GamePakWorldReadyStage.CatchUpBatchComplete));
        }

        // Source: Comms/Comms.Drt/Func/Server/Set/ServerGame.cs:ServerGame.SendDataMessageToAllClients
        private void CompleteJoiningClient(int sourceClientId, int transferId,
            JoinCatchUpJournal journal)
        {
            // Source: ScMultiplayer.cs:ScMultiplayer.SealAndSendJoinCatchUp
            // Drain the bounded post-cutoff gap once. This callback runs on the frame thread, so
            // enabling normal traffic afterwards cannot leave an unrecorded interval.
            DrainPostCutoffJournal(sourceClientId, journal);
            GetOrCreatePendingJoinCatchUp(sourceClientId).CompletionAction = () =>
                FinishJoiningClient(sourceClientId, transferId, journal);
        }

        private void FinishJoiningClient(int sourceClientId, int transferId,
            JoinCatchUpJournal journal)
        {
            m_joinCatchUpJournals.Remove(sourceClientId);
            m_worldTransfersAwaitingReady.Remove(sourceClientId);
            m_hostProjectReadyTransfers.Remove(sourceClientId);
            m_completedWorldReadyTransfers[sourceClientId] = transferId;
            NetworkMessageSender.SendPakWorldReady(sourceClientId,
                new GamePakWorldReadyMessage(transferId,
                    GamePakWorldReadyStage.ReadyToPlay));
            SetServerClientGameTrafficEnabled(sourceClientId, enabled: true);
            m_fullWorldObjectsSyncTime = WorldObjectFullSyncInterval;
            m_fullAnimalSyncTime = 5f;
            Log.Information($"[ScMP] World transfer ready: ClientID={sourceClientId}, " +
                $"Transfer={transferId}, CatchUpRounds={journal.ReplayRound}, " +
                $"CatchUpMessages={journal.TotalMessagesSent}, " +
                $"CatchUpBytes={journal.TotalBytesSent}, Dropped={journal.DroppedMessages}");
        }

        public void HandleGamePakWorldMessage(GamePakWorldMessage msg)
        {
            if (msg == null || (msg.TargetClientId >= 0 && msg.TargetClientId != client.ClientID))
                return;
            if (msg.TransferId > 0 && msg.ChunkCount > 0)
            {
                IncomingWorldTransfer transfer = GetOrCreateIncomingWorldTransfer(
                    msg.TransferId, msg.TargetClientId, msg.ChunkCount, msg.TotalLength);
                if (transfer == null) return;
                if (msg.WorldSha256 == null || msg.WorldSha256.Length != 32)
                {
                    Log.Error($"[ScMP] Invalid world checksum manifest: Transfer={msg.TransferId}");
                    return;
                }
                bool receivedNewManifest = transfer.Manifest == null;
                transfer.Manifest = msg;
                transfer.LastProgressTime = Time.RealTime;
                if (receivedNewManifest) RecordClientJoinProgress();
                TryCompleteIncomingWorldTransfer(transfer);
                return;
            }
            if (msg.WorldData == null || msg.WorldData.Length == 0) return;
            m_joinAwaitingWorldProgress = false;
            m_sessionRandomSeed = msg.RandomSeed;
            m_pendingTerrainSequenceBaseline = msg.TerrainSequenceBaseline;
            m_pendingRandomStates = msg.RandomStates ?? new Dictionary<string, long>();
            m_randomStateAppliedProject = null;
            m_pendingLocalPlayerRecord = new NetworkPlayerRecord
            {
                Name = msg.PlayerName,
                PlayerClass = msg.PlayerClass,
                SkinName = msg.SkinName,
                SkinSha256 = CloneBytes(msg.SkinSha256),
                Position = msg.PlayerPosition,
                Level = msg.PlayerLevel,
                Health = msg.PlayerHealth,
                Air = msg.PlayerAir,
                Food = msg.PlayerFood,
                Stamina = msg.PlayerStamina,
                Sleep = msg.PlayerSleep,
                Temperature = msg.PlayerTemperature,
                TargetTemperature = msg.PlayerTargetTemperature,
                Wetness = msg.PlayerWetness,
                FluDuration = msg.PlayerFluDuration,
                FluOnset = msg.PlayerFluOnset,
                SicknessDuration = msg.PlayerSicknessDuration,
                BodyRotation = msg.PlayerBodyRotation,
                LookAngles = msg.PlayerLookAngles,
                FireDuration = msg.PlayerFireDuration,
                Satiation = msg.PlayerSatiation ?? new Dictionary<int, float>(),
                IsCreativeFlying = msg.PlayerIsCreativeFlying,
                HasReceivedInitialItems = msg.HasReceivedInitialItems,
                InventoryWasCreative = msg.InventoryWasCreative,
                ActiveSlotIndex = msg.ActiveSlotIndex,
                CreativeCategoryIndex = msg.CreativeCategoryIndex,
                CreativePageIndex = msg.CreativePageIndex,
                SlotValues = msg.SlotValues,
                SlotCounts = msg.SlotCounts,
                HandcraftSlotValues = msg.HandcraftSlotValues,
                HandcraftSlotCounts = msg.HandcraftSlotCounts,
                Clothes = msg.Clothes
            };
            m_localReplacementPlayerData = null;
            m_localPlayerRecordQueued = false;
            m_localPlayerRecordApplied = false;
            try
            {
                Log.Information($"[ScMP] Importing world: {msg.Name} ({msg.WorldData.Length} bytes)");
                // Source: Survivalcraft/Game/WorldsManager.cs:WorldsManager.ImportWorld
                // Network worlds keep EmbeddedContent as session assets. The native import path
                // writes embedded skins/textures into global Content folders, which would pollute
                // the user's local library after joining other rooms.
                var existingDirectories = new HashSet<string>(WorldsManager.WorldInfos.Select(world => world.DirectoryName));
                string importedDirectory = ImportNetworkWorld(new MemoryStream(msg.WorldData));
                m_downloadedWorldDirectory = importedDirectory;
                RegisterDownloadedWorld(importedDirectory);
                WorldsManager.UpdateWorldsList();

                WorldInfo importedWorld = WorldsManager.WorldInfos.FirstOrDefault(world =>
                    world.DirectoryName == importedDirectory);
                if (importedWorld == null)
                    importedWorld = WorldsManager.WorldInfos.FirstOrDefault(world =>
                        !existingDirectories.Contains(world.DirectoryName) &&
                        world.WorldSettings.Name == msg.Name);
                if (importedWorld == null)
                    importedWorld = WorldsManager.WorldInfos.FirstOrDefault(world =>
                        world.WorldSettings.Name == msg.Name && world.LastSaveTime == msg.LastSaveTime);
                if (importedWorld != null)
                {
                    if (m_joinRoomBusyDialog != null)
                        m_joinRoomBusyDialog.SmallMessage =
                            "Connected.\r\nWorld imported.\r\nLoading project...";
                    SuPlayScreen.Play(importedWorld);
                    connectionSM.TransitionTo(NetworkConnectionStateMachine.ConnectionState.Playing);
                    m_shouldCreateHostAvatar = true;
                    m_pendingNetworkPlayers[0] = "Host";
                    m_pendingNetworkPlayerIdentities[0] = GetNetworkRecordKey(0);
                    // Source: Survivalcraft/Game/GameManager.cs:GameManager.Project
                    // Play() starts loading asynchronously. Acknowledging here lets catch-up
                    // messages arrive before the imported Project exists, so defer Ready until
                    // UpdateWorldSubsystem observes the initialized Project.
                    if (msg.TransferId > 0)
                    {
                        m_pendingWorldReadyTransferId = msg.TransferId;
                        m_pendingCircuitReadyTransferId = 0;
                        m_projectReadySentProject = null;
                        m_projectReadySentTransferId = 0;
                        m_nextClientJoinReadyRetryTime = 0.0;
                        RecordClientJoinProgress();
                        NetworkMessageSender.SendPakWorldReady(
                            new GamePakWorldReadyMessage(msg.TransferId,
                                GamePakWorldReadyStage.LoadingProject));
                    }
                    Log.Information($"[ScMP] World imported, entering game: {importedWorld.DirectoryName}");
                    return;
                }
                Log.Error($"[ScMP] World imported but not found in world list: {msg.Name}");
                m_clientWorldRefreshProject = null;
                m_isLoadingDownloadedWorld = false;
                HideJoinRoomBusyDialog();
                DialogsManager.ShowDialog(null, new MessageDialog(
                    "Join Room", "The downloaded host world could not be opened.",
                    "OK", null, null));
            }
            catch (Exception ex)
            {
                m_clientWorldRefreshProject = null;
                m_isLoadingDownloadedWorld = false;
                HideJoinRoomBusyDialog();
                Log.Error($"[ScMP] Failed to import world: {ex.Message}");
                DialogsManager.ShowDialog(null, new MessageDialog(
                    "Join Room", "Failed to load the host world: " + ex.Message,
                    "OK", null, null));
            }
        }

        // Source: Survivalcraft/Game/WorldsManager.cs:WorldsManager.ImportWorld
        // Source: Survivalcraft/Game/WorldsManager.cs:WorldsManager.UnpackWorld
        private string ImportNetworkWorld(Stream sourceStream)
        {
            if (MarketplaceManager.IsTrialMode)
                throw new InvalidOperationException("Cannot import worlds in trial mode.");
            if (WorldsManager.WorldInfos.Count >= 30)
                throw new InvalidOperationException(
                    "Too many worlds on device, maximum allowed is 30. Delete some to free up space.");
            string directoryName = GetUnusedNetworkWorldDirectoryName();
            var sessionAssets = new NetworkWorldSessionAssets();
            Storage.CreateDirectory(directoryName);
            try
            {
                using Game.ZipArchive zipArchive =
                    Game.ZipArchive.Open(sourceStream, keepStreamOpen: true);
                foreach (Game.ZipArchiveEntry entry in zipArchive.ReadCentralDir())
                {
                    string filename = NormalizeNetworkWorldZipPath(entry.FilenameInZip);
                    if (string.IsNullOrEmpty(filename)) continue;
                    string extension = Storage.GetExtension(filename).ToLowerInvariant();
                    if (filename.StartsWith("EmbeddedContent/", StringComparison.OrdinalIgnoreCase))
                    {
                        ImportNetworkWorldEmbeddedAsset(zipArchive, entry, filename,
                            extension, sessionAssets);
                        continue;
                    }
                    string path = Storage.CombinePaths(directoryName, filename);
                    Storage.CreateDirectory(Storage.GetDirectoryName(path));
                    using Stream target = Storage.OpenFile(path, OpenFileMode.Create);
                    zipArchive.ExtractFile(entry, target);
                }
                if (!TestNetworkWorldProjectXml(directoryName))
                    throw new InvalidOperationException(
                        "Cannot import world because it does not contain valid world data.");
                m_networkWorldSessionAssets = sessionAssets;
                return directoryName;
            }
            catch
            {
                try { WorldsManager.DeleteWorld(directoryName); }
                catch { }
                ClearNetworkWorldSessionAssets(sessionAssets);
                throw;
            }
        }

        private static string GetUnusedNetworkWorldDirectoryName()
        {
            string root = Storage.CombinePaths("data:/Worlds", "World");
            for (int i = 0; i < 1000; i++)
            {
                string directory = Storage.CombinePaths(Storage.GetDirectoryName(root),
                    Storage.GetFileNameWithoutExtension(root) +
                    (i > 0 ? i.ToString(CultureInfo.InvariantCulture) : string.Empty) +
                    Storage.GetExtension(root));
                if (!Storage.DirectoryExists(directory) && !Storage.FileExists(directory))
                    return directory;
            }
            throw new InvalidOperationException("Out of filenames for network world import.");
        }

        private static string NormalizeNetworkWorldZipPath(string filename)
        {
            string text = (filename ?? string.Empty).Replace('\\', '/').Trim();
            if (text.Length == 0 || text.EndsWith("/", StringComparison.Ordinal) ||
                text.StartsWith("/", StringComparison.Ordinal) ||
                text.Split('/').Any(part => part == ".."))
                return string.Empty;
            return text;
        }

        private void ImportNetworkWorldEmbeddedAsset(Game.ZipArchive zipArchive,
            Game.ZipArchiveEntry entry, string filename, string extension,
            NetworkWorldSessionAssets sessionAssets)
        {
            try
            {
                if (extension == ".scskin")
                {
                    if (entry.FileSize > MaximumSkinAssetBytes) return;
                    byte[] data = ExtractZipEntryBytes(zipArchive, entry,
                        MaximumSkinAssetBytes);
                    byte[] hash = SHA256.HashData(data);
                    string skinName = Storage.GetFileName(filename);
                    StoreSessionSkinAsset(0, skinName,
                        CharacterSkinsManager.GetPlayerClass(skinName) ?? PlayerClass.Male,
                        hash, data);
                    return;
                }
                if (extension == ".scbtex")
                {
                    if (entry.FileSize > MaximumBlocksTextureAssetBytes ||
                        sessionAssets.BlocksTextureData.Length > 0)
                        return;
                    byte[] data = ExtractZipEntryBytes(zipArchive, entry,
                        MaximumBlocksTextureAssetBytes);
                    ValidateBlocksTextureAssetData(data);
                    sessionAssets.BlocksTextureName = Storage.GetFileName(filename);
                    sessionAssets.BlocksTextureData = data;
                }
            }
            catch (Exception ex)
            {
                Log.Warning($"[ScMP] Skipped embedded network asset \"{filename}\": {ex.Message}");
            }
        }

        private static byte[] ExtractZipEntryBytes(Game.ZipArchive zipArchive,
            Game.ZipArchiveEntry entry, int maximumBytes)
        {
            using var memory = new MemoryStream();
            zipArchive.ExtractFile(entry, memory);
            if (memory.Length > maximumBytes)
                throw new InvalidOperationException($"Asset is larger than {maximumBytes} bytes.");
            return memory.ToArray();
        }

        // Source: Survivalcraft/Game/BlocksTexturesManager.cs:BlocksTexturesManager.ValidateBlocksTexture
        private static Image ValidateBlocksTextureAssetData(byte[] data)
        {
            if (data == null || data.Length == 0 ||
                data.Length > MaximumBlocksTextureAssetBytes)
                throw new InvalidOperationException("Invalid blocks texture size.");
            Image image = Image.Load(new MemoryStream(data));
            if (image.Width > 1024 || image.Height > 1024)
                throw new InvalidOperationException(
                    $"Blocks texture is larger than 1024x1024 pixels (size={image.Width}x{image.Height}).");
            if (!MathUtils.IsPowerOf2(image.Width) || !MathUtils.IsPowerOf2(image.Height))
                throw new InvalidOperationException(
                    $"Blocks texture does not have power-of-two size (size={image.Width}x{image.Height}).");
            return image;
        }

        private static bool TestNetworkWorldProjectXml(string directoryName)
        {
            try
            {
                string fileName = Storage.CombinePaths(directoryName, "Project.xml");
                if (!Storage.FileExists(fileName)) return false;
                using Stream stream = Storage.OpenFile(fileName, OpenFileMode.Read);
                XElement element = XElement.Load(stream);
                return element.Name == "Project";
            }
            catch
            {
                return false;
            }
        }

        // Source: Survivalcraft/Game/SubsystemBlocksTexture.cs:SubsystemBlocksTexture.LoadBlocksTexture
        // Source: Survivalcraft/Game/SubsystemAnimatedTextures.cs:SubsystemAnimatedTextures.Update
        private void ApplyNetworkWorldTexture(Project project)
        {
            NetworkWorldSessionAssets assets = m_networkWorldSessionAssets;
            if (IsHost || project == null || assets == null ||
                assets.BlocksTextureData == null || assets.BlocksTextureData.Length == 0 ||
                assets.BlocksTextureLoadFailed)
                return;
            SubsystemGameInfo gameInfo = project.FindSubsystem<SubsystemGameInfo>(false);
            string expectedName = gameInfo?.WorldSettings.BlocksTextureName ?? string.Empty;
            if (BlocksTexturesManager.IsBuiltIn(expectedName) ||
                (!string.IsNullOrEmpty(assets.BlocksTextureName) &&
                !string.Equals(assets.BlocksTextureName, expectedName,
                    StringComparison.OrdinalIgnoreCase)))
                return;
            if (assets.BlocksTexture == null)
            {
                try
                {
                    Image image = ValidateBlocksTextureAssetData(assets.BlocksTextureData);
                    assets.BlocksTexture = Texture2D.Load(image);
                    assets.BlocksTexture.Tag = image;
                }
                catch (Exception ex)
                {
                    assets.BlocksTextureLoadFailed = true;
                    Log.Warning($"[ScMP] Could not create session blocks texture \"{expectedName}\": {ex.Message}");
                    return;
                }
            }
            SubsystemBlocksTexture subsystemBlocksTexture =
                project.FindSubsystem<SubsystemBlocksTexture>(false);
            if (subsystemBlocksTexture == null) return;
            Texture2D currentTexture = subsystemBlocksTexture.BlocksTexture;
            if (ReferenceEquals(currentTexture, assets.BlocksTexture))
            {
                assets.AppliedProject = project;
                return;
            }
            if (currentTexture != null && !ContentManager.IsContent(currentTexture))
                currentTexture.Dispose();
            ModManager.ModParentField.ModifyParentField(subsystemBlocksTexture,
                "<BlocksTexture>k__BackingField", assets.BlocksTexture,
                typeof(SubsystemBlocksTexture));
            ResetAnimatedBlocksTexture(project);
            assets.AppliedProject = project;
        }

        private static void ResetAnimatedBlocksTexture(Project project)
        {
            SubsystemAnimatedTextures animatedTextures =
                project?.FindSubsystem<SubsystemAnimatedTextures>(false);
            if (animatedTextures == null) return;
            RenderTarget2D renderTarget = ModManager.ModParentField
                .GetParentField<RenderTarget2D>(animatedTextures,
                    "m_animatedBlocksTexture", typeof(SubsystemAnimatedTextures));
            if (renderTarget != null) renderTarget.Dispose();
            ModManager.ModParentField.ModifyParentField(animatedTextures,
                "m_animatedBlocksTexture", null, typeof(SubsystemAnimatedTextures));
        }

        private void ClearSessionAssets()
        {
            m_sessionSkinAssets.Clear();
            m_playerSkinHashes.Clear();
            m_requestedSkinAssetKeys.Clear();
            m_incomingSkinAssetTransfers.Clear();
            m_sentLocalSkinAssetHashes.Clear();
            ClearNetworkWorldSessionAssets(m_networkWorldSessionAssets);
            m_networkWorldSessionAssets = null;
            m_lastLocalProfileSignature = null;
        }

        private static void ClearNetworkWorldSessionAssets(
            NetworkWorldSessionAssets assets)
        {
            if (assets?.BlocksTexture != null && assets.AppliedProject == null &&
                !ContentManager.IsContent(assets.BlocksTexture))
                assets.BlocksTexture.Dispose();
        }

