        {
            Log.Information($"[Server] {obj}");
        }

        // Source: Comms/Drt/GameStepData.Inputs
        // Remote host/peer avatars are presentation replicas. Extrapolate the last authoritative
        // snapshot to the current server step, then interpolate the visible body toward it.
        private void UpdateRemotePlayerPresentations(float dt)
        {
            foreach (KeyValuePair<int, NetworkPlayerState> item in RemotePlayers.ToArray())
            {
                NetworkPlayerState state = item.Value;
                if (state == null || Time.RealTime - state.LastUpdateTime > RemotePresentationStaleTime ||
                    !m_networkPlayerData.TryGetValue(item.Key, out PlayerData playerData) ||
                    playerData.ComponentPlayer?.ComponentBody == null)
                    continue;
                ComponentBody body = playerData.ComponentPlayer.ComponentBody;
                ComponentCreatureModel model = playerData.ComponentPlayer.ComponentCreatureModel;
                ComponentLocomotion locomotion = playerData.ComponentPlayer.ComponentLocomotion;
                // Source: Survivalcraft/Game/ComponentLocomotion.cs:ComponentLocomotion.NormalMovement
                // Creative flight disables gravity only while a movement order is present. A remote
                // presentation has no local PlayerInput, so preserve the authoritative flight mode
                // explicitly instead of letting the replica fall between snapshots.
                body.IsGravityEnabled = !state.IsFlying;
                body.IsGroundDragEnabled = !state.IsFlying;
                if (locomotion != null)
                {
                    locomotion.IsCreativeFlyEnabled = state.IsFlying;
                    ModManager.ModParentField.ModifyParentField(
                        locomotion, "m_lookAngles", state.LookAngles,
                        typeof(ComponentLocomotion));
                    ModManager.ModParentField.ModifyParentField(
                        locomotion, "<LastWalkOrder>k__BackingField", state.WalkOrder,
                        typeof(ComponentLocomotion));
                    ModManager.ModParentField.ModifyParentField(
                        locomotion, "<LastJumpOrder>k__BackingField", state.JumpOrder,
                        typeof(ComponentLocomotion));
                }
                if (model != null)
                {
                    // Source: ComponentHumanModel.cs:ComponentHumanModel.Animate
                    // Orders are consumed and reset every animation frame, so replay the latest
                    // authoritative presentation state until the next snapshot changes it.
                    model.AttackOrder = state.AttackOrder;
                    model.RowLeftOrder = state.RowLeftOrder;
                    model.RowRightOrder = state.RowRightOrder;
                    model.InHandItemOffsetOrder = state.ItemOffset;
                    model.InHandItemRotationOrder = state.ItemRotation;
                    model.AimHandAngleOrder = state.AimHandAngle;
                }
                // Source: Comms.Drt/Func/Client/Client.cs:GetStepWaitTime
                // ZeroTier can briefly exceed the network tick interval by an order of magnitude.
                // Keep using a bounded latest-state prediction instead of freezing the avatar.
                float delaySample = MathUtils.Clamp(
                    (client.Step - state.ServerTick) * ServerTickDuration, 0f,
                    RemoteDelaySampleLimit);
                state.EstimatedDelay = state.EstimatedDelay <= 0f
                    ? delaySample
                    : MathUtils.Lerp(state.EstimatedDelay, delaySample, 0.12f);
                float extrapolationTime = MathUtils.Min(state.EstimatedDelay,
                    RemoteExtrapolationLimit);
                Vector3 targetPosition = state.Position;
                if (!state.IsFlying)
                {
                    targetPosition.X += state.Velocity.X * extrapolationTime;
                    targetPosition.Z += state.Velocity.Z * extrapolationTime;
                }
                if (!state.IsGrounded && !state.IsFlying)
                {
                    targetPosition.Y += state.Velocity.Y * extrapolationTime -
                        4.9f * extrapolationTime * extrapolationTime;
                }
                float errorSquared = Vector3.DistanceSquared(body.Position, targetPosition);
                if (!state.PresentationInitialized || errorSquared > 64f)
                {
                    // Snap only to an authoritative sampled position. An extrapolated descending
                    // point can already be below terrain before the next grounded packet arrives.
                    body.Position = state.Position;
                    body.Rotation = state.Rotation;
                    body.Velocity = state.Velocity;
                    state.PresentationInitialized = true;
                }
                else
                {
                    if (state.IsFlying)
                    {
                        // Source: Survivalcraft/Game/ComponentLocomotion.cs:ComponentLocomotion.CreativeFly
                        // A flying replica has no local input and must not integrate the previous
                        // snapshot velocity beyond its last authoritative position. Smooth the
                        // sampled positions directly and leave movement animation to WalkOrder.
                        float positionBlend = 1f - MathUtils.Pow(
                            0.001f, MathUtils.Min(dt, 0.1f));
                        body.Position = Vector3.Lerp(body.Position,
                            state.Position, positionBlend);
                        body.Velocity = Vector3.Zero;
                        body.Rotation = Quaternion.Slerp(
                            body.Rotation, state.Rotation, positionBlend);
                        continue;
                    }
                    float delayFactor = MathUtils.Saturate(state.EstimatedDelay / 0.2f);
                    Vector3 error = targetPosition - body.Position;
                    bool correctingHostKnockback =
                        Time.RealTime < state.KnockbackCorrectionUntil &&
                        state.ServerTick >= state.KnockbackCorrectionStartTick;
                    float deadZone = correctingHostKnockback
                        ? (state.IsGrounded ? 0.05f : 0.1f)
                        : (state.IsGrounded ? 0.4f : 0.1f);
                    Vector3 targetVelocity = state.Velocity;
                    if (state.IsGrounded) targetVelocity.Y = 0f;
                    Vector3 desiredVelocity;
                    float blend;
                    if (error.LengthSquared() <= deadZone * deadZone)
                    {
                        desiredVelocity = targetVelocity;
                        blend = 0.45f;
                    }
                    else
                    {
                        float horizon = MathUtils.Lerp(0.35f, 0.2f, delayFactor);
                        Vector3 catchUpVelocity = error / horizon;
                        float maxExtraSpeed = MathUtils.Lerp(3f, 8f, delayFactor);
                        float extraSpeed = catchUpVelocity.Length();
                        if (extraSpeed > maxExtraSpeed)
                            catchUpVelocity *= maxExtraSpeed / extraSpeed;
                        desiredVelocity = targetVelocity + catchUpVelocity;
                        blend = MathUtils.Lerp(0.2f, 0.35f, delayFactor);
                    }
                    // Source: Survivalcraft/Game/ComponentBody.cs:ComponentBody.Update
                    // An airborne remote avatar must leave the ground promptly. The old 0.65m
                    // vertical dead zone could keep its presentation body visibly grounded through
                    // most of a short jump even though the host position was already airborne.
                    if (!state.IsGrounded)
                        blend = MathUtils.Max(blend, 0.45f);
                    body.Velocity = Vector3.Lerp(body.Velocity, desiredVelocity, blend);
                    body.Rotation = Quaternion.Slerp(body.Rotation, state.Rotation, 0.4f);
                }
            }
        }

        // Source: Survivalcraft/Game/ComponentLocomotion.cs:ComponentLocomotion.NormalMovement
        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.AttackBody
        // Capture ApplyImpulse before remote-follow correction can replace it with the client's
        // pre-hit velocity. StunTime also covers armored/invulnerable hits with zero health loss.
        private void CaptureHostRemoteKnockbacks()
        {
            double now = Time.RealTime;
            foreach (KeyValuePair<int, PlayerData> remote in m_networkPlayerData.ToArray())
            {
                if (remote.Key <= 0 || remote.Value?.ComponentPlayer == null) continue;
                ComponentPlayer player = remote.Value.ComponentPlayer;
                ComponentHealth health = player.ComponentHealth;
                ComponentBody body = player.ComponentBody;
                if (health == null || body == null) continue;
                if (!m_hostKnockbackHealthCache.TryGetValue(remote.Key, out float previousHealth))
                {
                    m_hostKnockbackHealthCache[remote.Key] = health.Health;
                    continue;
                }

                bool healthDecreased = health.Health < previousHealth - 0.0001f;
                bool alreadyHeld = m_hostRemoteKnockbackUntil.TryGetValue(
                    remote.Key, out double heldUntil) && heldUntil > now;
                float knockbackStunTime = MathUtils.Max(
                    player.ComponentLocomotion?.StunTime ?? 0f, 0f);
                bool attackStun = knockbackStunTime > 0f;
                if ((healthDecreased || (attackStun && !alreadyHeld)) &&
                    body.Velocity.LengthSquared() > 0.0001f)
                {
                    float lastSentHealth = m_lastSentAuthoritativePlayerStates.TryGetValue(
                        remote.Key, out AuthoritativePlayerStateSnapshot lastSentState)
                        ? lastSentState.Health
                        : previousHealth;
                    m_hostKnockbackSequences.TryGetValue(remote.Key,
                        out int knockbackSequence);
                    knockbackSequence = knockbackSequence == int.MaxValue
                        ? 1
                        : knockbackSequence + 1;
                    m_hostKnockbackSequences[remote.Key] = knockbackSequence;
                    // Source: Survivalcraft/Game/ComponentBody.cs:ComponentBody.Update
                    // Keep client-follow correction out of the entire knockback trajectory. The
                    // host therefore retains the original drag, gravity and collision decay, while
                    // the owning client follows the authoritative position snapshots it produces.
                    m_hostRemoteKnockbackUntil[remote.Key] = now +
                        LocalKnockbackPositionCorrectionDuration;
                    NetworkMessageSender.SendPlayerHealthMessage(
                        remote.Key, player, health.Health - lastSentHealth,
                        hasKnockback: true,
                        knockbackSequence: knockbackSequence,
                        knockbackServerTick: client.Step,
                        knockbackStunTime: knockbackStunTime);
                    if (player.ComponentVitalStats != null)
                        m_lastSentAuthoritativePlayerStates[remote.Key] =
                            CaptureAuthoritativePlayerState(player);
                }
                m_hostKnockbackHealthCache[remote.Key] = health.Health;
            }
            foreach (int clientId in m_hostKnockbackHealthCache.Keys.Where(
                id => !m_networkPlayerData.ContainsKey(id)).ToArray())
            {
                m_hostKnockbackHealthCache.Remove(clientId);
                m_hostRemoteKnockbackUntil.Remove(clientId);
                m_hostKnockbackSequences.Remove(clientId);
            }
        }

        // Source: Mod/Comms/Comms/PeerData.cs:PeerData.Ping
        // Ping is a round-trip measurement. A client transform packet reaches the host after
        // approximately half that time, so position prediction must use RTT / 2 rather than a
        // difference between independently advancing simulation steps.
        private void SampleRemotePositionRtt(
            int clientId, NetworkPlayerInputState state)
        {
            if (clientId <= 0 || state == null || server?.Peer == null || client == null)
                return;
            // Source: Mod/Comms/Comms/Peer.cs:Peer.KeepAliveResponseMessage.Handle
            // PeerData.Ping changes much more slowly than input snapshots. Sampling it at 4 Hz
            // prevents one unchanged probe result from being counted as dozens of stable samples.
            double now = Time.RealTime;
            if (now < state.NextPositionRttSampleTime) return;
            state.NextPositionRttSampleTime = now + 0.25;
            float ping = 0f;
            try
            {
                lock (server.Peer.Lock)
                {
                    ServerGame game = server.Games.FirstOrDefault(item =>
                        item.GameID == client.GameID);
                    ServerClient remoteClient = game?.Clients.FirstOrDefault(item =>
                        item.ClientID == clientId);
                    PeerData peer = remoteClient == null
                        ? null
                        : server.Peer.FindPeer(remoteClient.Address);
                    ping = peer?.Ping ?? 0f;
                }
            }
            catch
            {
                return;
            }
            if (ping <= 0f || float.IsNaN(ping) || float.IsInfinity(ping))
                return;

            ping = MathUtils.Clamp(ping, 0f, 2f * RemoteDelaySampleLimit);
            state.LatestPositionRtt = ping;
            if (state.SmoothedPositionRtt <= 0f)
            {
                state.SmoothedPositionRtt = ping;
                state.PositionRttDeviation = 0f;
            }
            else
            {
                float deviation = MathUtils.Abs(ping - state.SmoothedPositionRtt);
                state.PositionRttDeviation = MathUtils.Lerp(
                    state.PositionRttDeviation, deviation, 0.1f);
                state.SmoothedPositionRtt = MathUtils.Lerp(
                    state.SmoothedPositionRtt, ping, 0.1f);
            }
        }

        // Source: Mod/Comms/Comms/PeerData.cs:PeerData.Ping
        private static float GetRemotePositionPredictionTime(NetworkPlayerInputState state)
        {
            if (state == null || state.SmoothedPositionRtt <= 0f) return 0f;
            // Source: Mod/ScMultiplayer/Func/Circuit/CircuitSynchronizer.cs:
            // CircuitSynchronizer.GetCircuitLeadSteps
            // Do not react to a single high RTT sample by moving the avatar farther ahead. A low
            // sample can reduce lead immediately; a sustained increase is admitted by the EWMA.
            float stableThreshold = MathUtils.Max(
                0.005f, 0.25f * state.SmoothedPositionRtt);
            bool stable = state.PositionRttDeviation <= stableThreshold;
            float effectiveRtt = stable
                ? state.SmoothedPositionRtt
                : MathUtils.Min(state.LatestPositionRtt, state.SmoothedPositionRtt);
            return 0.5f * effectiveRtt;
        }

        // Source: Survivalcraft/Game/ComponentLocomotion.cs:ComponentLocomotion.NormalMovement
        // Original host locomotion remains authoritative. Client position samples can only add a
        // bounded correction that does not point backwards relative to the client's current travel.
        private void ApplyHostRemoteFollowVelocities()
        {
            foreach (KeyValuePair<int, PlayerData> remote in m_networkPlayerData.ToArray())
            {
                if (remote.Key <= 0 || remote.Value?.ComponentPlayer == null ||
                    !m_networkPlayerInputs.TryGetValue(remote.Key, out NetworkPlayerInputState state) ||
                    Time.RealTime - state.LastReceivedTime > RemoteInputHoldDuration)
                    continue;
                if (m_hostRemoteKnockbackUntil.TryGetValue(remote.Key, out double knockbackUntil))
                {
                    if (Time.RealTime < knockbackUntil) continue;
                    m_hostRemoteKnockbackUntil.Remove(remote.Key);
                }
                ComponentPlayer player = remote.Value.ComponentPlayer;
                if (player.ComponentRider?.Mount != null)
                    continue;
                ComponentBody body = player.ComponentBody;
                ComponentLocomotion locomotion = player.ComponentLocomotion;
                float delay = GetRemotePositionPredictionTime(state);
                // Source: Survivalcraft/Game/ComponentBody.cs:ComponentBody.StanceBoxSize
                // Host locomotion already advances the remote replica from its input. Limit the
                // additional network look-ahead to half a body width so latency compensation does
                // not place it several blocks ahead and then visibly pull it back.
                Vector3 predictionOffset = state.BodyVelocity * delay;
                float maximumPredictionDistance = 0.5f * MathUtils.Max(
                    body.StanceBoxSize.X, body.StanceBoxSize.Z);
                float predictionDistance = predictionOffset.Length();
                if (predictionDistance > maximumPredictionDistance &&
                    predictionDistance > 0.0001f)
                {
                    predictionOffset *= maximumPredictionDistance / predictionDistance;
                }
                Vector3 targetPosition = state.BodyPosition + predictionOffset;
                Vector3 error = targetPosition - body.Position;
                Vector3 travelVelocity = state.BodyVelocity;
                // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
                // Use the current movement order as direction authority. BodyVelocity can still
                // point along the previous direction for a frame after a rapid reversal.
                Vector3 localIntent = body.CrouchFactor > 0f
                    ? 0.66f * state.Input.CrouchMove
                    : state.Input.Move;
                Vector3 right = body.Matrix.Right;
                Vector3 forward = body.Matrix.Forward;
                Vector3 travelIntent;
                if (!locomotion.IsCreativeFlyEnabled)
                {
                    // Source: ComponentLocomotion.NormalMovement
                    // Ground locomotion and jumping remain host-simulated. A delayed client height
                    // must not overwrite gravity, collision response or the native jump arc.
                    error.Y = 0f;
                    travelVelocity.Y = 0f;
                    right.Y = 0f;
                    forward.Y = 0f;
                    if (right.LengthSquared() > 0.0001f) right = Vector3.Normalize(right);
                    if (forward.LengthSquared() > 0.0001f) forward = Vector3.Normalize(forward);
                    travelIntent = right * localIntent.X + forward * localIntent.Z;
                }
                else
                    travelIntent = right * localIntent.X + Vector3.UnitY * localIntent.Y +
                        forward * localIntent.Z;

                float intentLength = travelIntent.Length();
                if (intentLength < 0.05f && locomotion.IsCreativeFlyEnabled)
                {
                    // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
                    // Creative flight can keep vertical velocity after the input rose returns to
                    // center. Fall back to the sampled position/velocity so a purely vertical rise
                    // is not frozen until the player also supplies horizontal movement.
                    travelIntent = error.LengthSquared() > 0.0025f
                        ? error
                        : travelVelocity;
                    intentLength = travelIntent.Length();
                }
                // Source: Survivalcraft/Game/ComponentBody.cs:ComponentBody.StandingOnValue
                // The client owns its sampled ground contact. Host-side replicas can otherwise
                // drift a few centimeters beyond a ledge and fall forever because normal ground
                // tracking intentionally ignores vertical error.
                bool clientStanding = state.IsGrounded &&
                    !locomotion.IsCreativeFlyEnabled &&
                    MathUtils.Abs(state.BodyVelocity.Y) < 0.5f &&
                    body.Velocity.Y < 0.1f;
                if (clientStanding)
                {
                    Vector3 groundedError = state.BodyPosition - body.Position;
                    if (MathUtils.Abs(groundedError.Y) > 0.025f)
                    {
                        body.Position = new Vector3(
                            body.Position.X, state.BodyPosition.Y, body.Position.Z);
                    }
                    body.Velocity = new Vector3(
                        body.Velocity.X, state.BodyVelocity.Y, body.Velocity.Z);
                    if (intentLength < 0.05f)
                    {
                        // Source: Mod/ScMultiplayer/Message/GamePlayerInputMessage.cs:BodyPosition
                        // No movement order means the old direction-based correction has no axis
                        // to follow. Re-anchor the stationary replica to the fresh client sample;
                        // cap a large recovery to one block per frame instead of teleporting.
                        groundedError = state.BodyPosition - body.Position;
                        float correctionLength = groundedError.Length();
                        Vector3 correction = correctionLength > 1f
                            ? groundedError / correctionLength
                            : groundedError;
                        body.Position += correction;
                        body.Velocity = state.BodyVelocity;
                        continue;
                    }
                }
                if (intentLength < 0.05f)
                    continue;
                Vector3 travelDirection = travelIntent / intentLength;
                float forwardError = Vector3.Dot(error, travelDirection);
                if (forwardError < 0f)
                {
                    // The host replica is already ahead of the delayed client sample. Remove only
                    // that reverse component instead of pulling the visible avatar backwards.
                    error -= travelDirection * forwardError;
                }
                float staleVelocity = Vector3.Dot(travelVelocity, travelDirection);
                if (staleVelocity < 0f)
                    travelVelocity -= travelDirection * staleVelocity;

                float trackingRadius = locomotion.IsCreativeFlyEnabled ? 32f : 16f;
                float errorLength = error.Length();
                if (errorLength > trackingRadius)
                {
                    error *= trackingRadius / errorLength;
                    errorLength = trackingRadius;
                }

                bool isInteracting = state.Input.Dig.HasValue || state.Input.Hit.HasValue ||
                    state.Input.Interact.HasValue || state.Input.Aim.HasValue;
                float deadZone = locomotion.IsCreativeFlyEnabled ? 0.35f : 0.15f;
                if (errorLength <= deadZone)
                    continue;

                float delayFactor = MathUtils.Saturate(delay / 0.2f);
                float horizon = MathUtils.Lerp(0.45f, 0.22f, delayFactor);
                Vector3 catchUpVelocity = error / horizon;
                float maxExtraSpeed = locomotion.IsCreativeFlyEnabled
                    ? MathUtils.Lerp(4f, 10f, delayFactor)
                    : MathUtils.Lerp(2f, 6f, delayFactor);
                float extraSpeed = catchUpVelocity.Length();
                if (extraSpeed > maxExtraSpeed)
                    catchUpVelocity *= maxExtraSpeed / extraSpeed;
                Vector3 desiredVelocity = travelVelocity + catchUpVelocity;
                if (!locomotion.IsCreativeFlyEnabled)
                    desiredVelocity.Y = body.Velocity.Y;
                float blend = MathUtils.Lerp(0.14f, 0.28f, delayFactor);
                if (isInteracting) blend = MathUtils.Max(blend, 0.35f);
                // Source: ComponentLocomotion.NormalMovement
                // Blend only while the host is behind the current direction of travel. Preserve
                // the host vertical velocity so gravity, jumping and collision response stay native.
                body.Velocity = Vector3.Lerp(body.Velocity, desiredVelocity, blend);
            }
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Update
        private void UpdateRemoteDigPresentations()
        {
            if (m_remoteDigPresentations.Count == 0) return;
            SubsystemTime subsystemTime = GameManager.Project?.FindSubsystem<SubsystemTime>(false);
            if (subsystemTime == null) return;
            double now = Time.RealTime;
            foreach (KeyValuePair<int, RemoteDigPresentation> entry in
                m_remoteDigPresentations.ToArray())
            {
                if (now - entry.Value.LastUpdateTime > 0.35 ||
                    !m_networkPlayerData.TryGetValue(entry.Key, out PlayerData playerData) ||
                    playerData?.ComponentPlayer?.ComponentMiner == null)
                {
                    m_remoteDigPresentations.Remove(entry.Key);
                    continue;
                }
                ComponentMiner miner = playerData.ComponentPlayer.ComponentMiner;
                RemoteDigPresentation state = entry.Value;
                state.DisplayProgress = MathUtils.Lerp(state.DisplayProgress,
                    state.TargetProgress, 0.28f);
                ModManager.ModParentField.ModifyParentField(miner,
                    "<DigCellFace>k__BackingField", (CellFace?)state.CellFace,
                    typeof(ComponentMiner));
                ModManager.ModParentField.ModifyParentField(miner, "m_digProgress",
                    state.DisplayProgress, typeof(ComponentMiner));
                ModManager.ModParentField.ModifyParentField(miner, "m_digStartTime",
                    subsystemTime.GameTime - 0.25, typeof(ComponentMiner));
                ModManager.ModParentField.ModifyParentField(miner, "m_lastDigFrameIndex",
                    Time.FrameIndex, typeof(ComponentMiner));
            }
        }

        public void CaptureLocalPlayerInput(ComponentPlayer player, PlayerInput playerInput)
        {
            if (IsHost)
            {
                TrackHostTerrainPlaceIntent(player, playerInput.Interact);
                return;
            }
            if (client?.IsConnected != true || player == null ||
                m_networkPlayerData.Values.Contains(player.PlayerData))
                return;
            EnsureClientDropDragHost(player);
            // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
            // Touch hold supplies both Dig and Aim. The local player suppresses Dig when the held
            // item is aimable; preserve that resolved intent for the host-side replica as well.
            IInventory inventory = player.ComponentMiner?.Inventory;
            int activeSlot = inventory?.ActiveSlotIndex ?? -1;
            NormalizeCrossbowSlot(inventory, activeSlot);
            RememberLocalEquipmentSnapshot(inventory);
            UpdateLocalAimLifecycle(player, playerInput, inventory, activeSlot);
            if (playerInput.Aim.HasValue && inventory != null && activeSlot >= 0 &&
                activeSlot < inventory.SlotsCount)
            {
                int value = inventory.GetSlotValue(activeSlot);
                Block block = BlocksManager.Blocks[Terrain.ExtractContents(value)];
                if (block.IsAimable) playerInput.Dig = null;
            }
            UpdateLocalDigTarget(player, playerInput.Dig);
            UpdateLocalDigPresentation(player);
            UpdateLocalHitRequests(player, playerInput.Hit);
            UpdateLocalInteractRequests(player, playerInput.Interact);
            UpdateLocalDropRequests(player, playerInput.Drop);
            UpdateLocalJumpRequests(playerInput.Jump);
            // Aim uses its own edge-preserving lifecycle. Dig completion is authoritative through
            // TerrainDigRequestMessage; PokingPhase is synchronized separately for presentation.
            // Interact and Drop use reliable edges and must not execute again through snapshots.
            playerInput.Aim = null;
            playerInput.Drop = false;
            playerInput.Jump = false;
            m_localPlayerInput = SanitizeNetworkPlayerInput(playerInput);
            m_localPlayerInput.Dig = null;
            m_localPlayerInput.Hit = null;
            m_localPlayerInput.Interact = null;
            m_localInputBodyPosition = player.ComponentBody.Position;
            m_localInputBodyVelocity = player.ComponentBody.Velocity;
            m_localInputBodyRotation = player.ComponentBody.Rotation;
            m_localInputLookAngles = player.ComponentLocomotion.LookAngles;
            m_localInputSequence = m_localInputSequence == int.MaxValue
                ? 1
                : m_localInputSequence + 1;
            m_localInputResendsRemaining = 3;
            if (inventory != null)
            {
                m_lastLocalInventoryValues = Enumerable.Range(0, inventory.SlotsCount)
                    .Select(inventory.GetSlotValue).ToArray();
                m_lastLocalInventoryCounts = Enumerable.Range(0, inventory.SlotsCount)
                    .Select(inventory.GetSlotCount).ToArray();
            }
        }

        // Source: Survivalcraft/Game/GameWidget.cs:GameWidget.LoadContents
        // Source: Survivalcraft/Game/InventorySlotWidget.cs:InventorySlotWidget.DragHostWidget
        private void EnsureClientDropDragHost(ComponentPlayer player)
        {
            GameWidget gameWidget = player?.PlayerData?.GameWidget;
            if (gameWidget == null || ReferenceEquals(m_clientDropDragHostGameWidget, gameWidget))
                return;
            DragHostWidget dragHost = gameWidget.Children.Find<DragHostWidget>("DragHost",
                throwIfNotFound: false);
            if (dragHost == null || dragHost is SuNetworkDragHostWidget ||
                dragHost.IsDragInProgress || dragHost.ParentWidget == null)
                return;

            ContainerWidget parent = dragHost.ParentWidget;
            int childIndex = parent.Children.IndexOf(dragHost);
            var replacement = new SuNetworkDragHostWidget
            {
                Name = dragHost.Name,
                Tag = dragHost.Tag,
                IsVisible = dragHost.IsVisible,
                IsEnabled = dragHost.IsEnabled,
                IsHitTestVisible = dragHost.IsHitTestVisible,
                ClampToBounds = dragHost.ClampToBounds,
                Margin = dragHost.Margin,
                HorizontalAlignment = dragHost.HorizontalAlignment,
                VerticalAlignment = dragHost.VerticalAlignment,
                LayoutTransform = dragHost.LayoutTransform,
                RenderTransform = dragHost.RenderTransform
            };
            parent.Children.Remove(dragHost);
            parent.Children.Insert(childIndex, replacement);
            foreach (InventorySlotWidget slotWidget in gameWidget.AllChildren
                .OfType<InventorySlotWidget>())
            {
                ModManager.ModParentField.ModifyParentField(slotWidget, "m_dragHostWidget",
                    replacement, typeof(InventorySlotWidget));
            }
            m_clientDropDragHostGameWidget = gameWidget;
        }

        // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
        private void UpdateLocalDigTarget(ComponentPlayer player, Ray3? digRay)
        {
            if (!digRay.HasValue || player?.ComponentMiner == null)
            {
                m_localDigTarget = null;
                return;
            }
            TerrainRaycastResult? hit = player.ComponentMiner.Raycast<TerrainRaycastResult>(
                digRay.Value, RaycastMode.Digging, raycastTerrain: true,
                raycastBodies: false, raycastMovingBlocks: false);
            if (!hit.HasValue)
            {
                m_localDigTarget = null;
                return;
            }
            Point3 point = new Point3(hit.Value.CellFace.X, hit.Value.CellFace.Y,
                hit.Value.CellFace.Z);
            int expectedValue = Terrain.ReplaceLight(hit.Value.Value, 0);
            if (!m_localDigTarget.HasValue || m_localDigTarget.Value != point)
            {
                m_localDigTarget = point;
            }
            IInventory inventory = player.ComponentMiner.Inventory;
            int activeSlot = inventory?.ActiveSlotIndex ?? -1;
            int toolValue = inventory != null && activeSlot >= 0 && activeSlot < inventory.SlotsCount
                ? inventory.GetSlotValue(activeSlot)
                : 0;
            int toolCount = inventory != null && activeSlot >= 0 && activeSlot < inventory.SlotsCount
                ? inventory.GetSlotCount(activeSlot)
                : 0;
            if (!m_localTerrainDigIntents.TryGetValue(point,
                out LocalTerrainDigIntent intent) || intent.ExpectedValue != expectedValue)
            {
                intent = new LocalTerrainDigIntent
                {
                    ExpectedValue = expectedValue,
                    StartClientTick = client.Step
                };
                m_localTerrainDigIntents[point] = intent;
            }
            intent.DigRay = digRay.Value;
            intent.HitFace = hit.Value.CellFace.Face;
            intent.ActiveSlotIndex = activeSlot;
            intent.ToolValue = toolValue;
            intent.ToolCount = toolCount;
            intent.BodyPosition = player.ComponentBody.Position;
            intent.LastSeenTime = Time.RealTime;
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Dig
        private void UpdateLocalDigPresentation(ComponentPlayer player)
        {
            ComponentMiner miner = player?.ComponentMiner;
            CellFace? cellFace = m_localDigTarget.HasValue ? miner?.DigCellFace : null;
            bool active = cellFace.HasValue && miner.DigTime > 0f && miner.DigProgress < 1f;
            double now = Time.RealTime;
            bool changed = active != m_localDigPresentationActive ||
                (active && (!m_localDigPresentationFace.HasValue ||
                    m_localDigPresentationFace.Value.X != cellFace.Value.X ||
                    m_localDigPresentationFace.Value.Y != cellFace.Value.Y ||
                    m_localDigPresentationFace.Value.Z != cellFace.Value.Z ||
                    m_localDigPresentationFace.Value.Face != cellFace.Value.Face));
            if (!changed && (!active || now < m_nextLocalDigPresentationTime)) return;

            m_localDigPresentationSequence = m_localDigPresentationSequence == int.MaxValue
                ? 1
                : m_localDigPresentationSequence + 1;
            int x = active ? cellFace.Value.X : 0;
            int y = active ? cellFace.Value.Y : 0;
            int z = active ? cellFace.Value.Z : 0;
            int face = active ? cellFace.Value.Face : 0;
            NetworkMessageSender.SendDigPresentation(0, new DigPresentationMessage(
                client.ClientID, m_localDigPresentationSequence, active, x, y, z, face,
                active ? MathUtils.Saturate(miner.DigProgress) : 0f), latest: !changed);
            m_localDigPresentationActive = active;
            m_localDigPresentationFace = active ? cellFace : null;
            m_nextLocalDigPresentationTime = now + 0.125;
        }

        // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
        private void UpdateLocalAimLifecycle(ComponentPlayer player, PlayerInput playerInput,
            IInventory inventory, int activeSlot)
        {
            int itemValue = inventory != null && activeSlot >= 0 && activeSlot < inventory.SlotsCount
                ? inventory.GetSlotValue(activeSlot)
                : 0;
            bool isAimable = itemValue != 0 &&
                BlocksManager.Blocks[Terrain.ExtractContents(itemValue)].IsAimable;
            double now = Time.RealTime;

            if (playerInput.Aim.HasValue && isAimable)
            {
                Ray3 aim = playerInput.Aim.Value;
                if (!m_localAimActive || activeSlot != m_localAimSlot ||
                    Terrain.ExtractContents(itemValue) != Terrain.ExtractContents(m_localAimItemValue))
                {
                    if (m_localAimActive)
                        SendLocalAimEvent(player, PlayerAimAction.Cancel, m_localAimRay);
                    m_localAimSequence = m_localAimSequence == int.MaxValue
                        ? 1
                        : m_localAimSequence + 1;
                    m_localAimActive = true;
                    m_localAimSlot = activeSlot;
                    m_localAimItemValue = itemValue;
                    m_localAimItemCount = inventory.GetSlotCount(activeSlot);
                    m_localAimRay = aim;
                    m_lastAimUpdateSentTime = now;
                    SendLocalAimEvent(player, PlayerAimAction.Start, aim);
                }
                else
                {
                    m_localAimRay = aim;
                    // Source: Survivalcraft/Game/SubsystemMusketBlockBehavior.cs:OnAim
                    // A musket cocks its hammer during AimState.InProgress. Keep that updated
                    // data bit in the release snapshot; only preserve the previous value when
                    // native prediction has already consumed the item on the release frame.
                    if (itemValue != 0 && activeSlot == m_localAimSlot &&
                        Terrain.ExtractContents(itemValue) ==
                        Terrain.ExtractContents(m_localAimItemValue))
                    {
                        m_localAimItemValue = itemValue;
                        m_localAimItemCount = Math.Max(inventory.GetSlotCount(activeSlot), 1);
                    }
                    if (now - m_lastAimUpdateSentTime >= SyncPulseDuration)
                    {
                        m_lastAimUpdateSentTime = now;
                        SendLocalAimEvent(player, PlayerAimAction.Update, aim);
                    }
                }
                return;
            }

            if (!m_localAimActive) return;
            // Source: Survivalcraft/Game/SubsystemThrowableBlockBehavior.cs:
            // SubsystemThrowableBlockBehavior.OnAim
            // Client prediction can consume a throwable before this release edge is captured.
            // Keep the held pre-throw value for the authoritative Release when the same slot is
            // now empty; changing to a different non-empty item remains a Cancel.
            bool sameSlot = activeSlot == m_localAimSlot;
            bool sameItem = sameSlot &&
                ((isAimable &&
                    Terrain.ExtractContents(itemValue) ==
                    Terrain.ExtractContents(m_localAimItemValue)) ||
                    itemValue == 0);
            if (sameSlot && itemValue != 0 &&
                Terrain.ExtractContents(itemValue) ==
                Terrain.ExtractContents(m_localAimItemValue))
            {
                m_localAimItemValue = itemValue;
                m_localAimItemCount = Math.Max(inventory.GetSlotCount(activeSlot), 1);
            }
            // Source: Survivalcraft/Game/SubsystemMusketBlockBehavior.cs:
            // SubsystemMusketBlockBehavior.OnAim
            // Keep the item value/count captured at Start. Native prediction may already have
            // consumed the loaded shot by this release edge; the host must receive the
            // pre-action loaded value to execute the authoritative Completed transition.
            SendLocalAimEvent(player,
                sameItem ? PlayerAimAction.Release : PlayerAimAction.Cancel, m_localAimRay);
            m_localAimActive = false;
            m_localAimSlot = -1;
            m_localAimItemValue = 0;
            m_localAimItemCount = 0;
        }

        private void SendLocalAimEvent(ComponentPlayer player, PlayerAimAction action, Ray3 aim)
        {
            if (client?.IsConnected != true || player?.ComponentBody == null) return;
            bool isRelease = action == PlayerAimAction.Release;
            NetworkMessageSender.SendPlayerAimMessage(new PlayerAimMessage(
                m_localAimSequence, action, aim, m_localAimSlot, m_localAimItemValue,
                m_localAimItemCount, player.ComponentBody.Position,
                player.ComponentBody.Rotation,
                isRelease ? player.ComponentBody.Velocity : Vector3.Zero,
                isRelease ? client.Step : 0));
        }

        // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
        // Hit is a cooldown-limited edge, not continuous movement state. Send it reliably at the
        // same cadence the original ComponentPlayer accepts while local prediction remains native.
        private void UpdateLocalHitRequests(ComponentPlayer player, Ray3? hitRay)
        {
            if (!hitRay.HasValue || Time.RealTime < m_nextLocalHitRequestTime ||
                client?.IsConnected != true)
                return;
            m_nextLocalHitRequestTime = Time.RealTime + PlayerHitRequestInterval;
            m_localHitSequence = m_localHitSequence == int.MaxValue ? 1 : m_localHitSequence + 1;
            TrackLocalMeleePrediction(player, m_localHitSequence);
            NetworkMessageSender.SendPlayerHitRequest(new PlayerActionMessage(
                PlayerActionType.HitRequest, client.ClientID, m_localHitSequence, hitRay.Value));
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Hit
        private void TrackLocalMeleePrediction(ComponentPlayer player, int sequence)
        {
            ComponentMiner miner = player?.ComponentMiner;
            if (miner == null || sequence <= 0) return;
            foreach (int expired in m_localMeleePredictions.Where(item =>
                Time.RealTime - item.Value.CreatedTime > 3.0).Select(item => item.Key).ToArray())
                m_localMeleePredictions.Remove(expired);
            m_localMeleePredictions[sequence] = new LocalMeleePrediction
            {
                Miner = miner,
                PreviousHitTime = ModManager.ModParentField.GetParentField<double>(
                    miner, "m_lastHitTime", typeof(ComponentMiner)),
                CreatedTime = Time.RealTime
            };
        }

        // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
        // Interact/Use/Place is already a one-frame input edge. Include the inventory state and
        // bind a possible terrain prediction to this request before native local execution.
        private void UpdateLocalInteractRequests(ComponentPlayer player, Ray3? interactRay)
        {
            if (!interactRay.HasValue || client?.IsConnected != true ||
                player?.ComponentMiner?.Inventory == null)
                return;
            IInventory inventory = player.ComponentMiner.Inventory;
            int activeSlot = inventory.ActiveSlotIndex;
            if (activeSlot < 0 || activeSlot >= inventory.SlotsCount) return;
            int itemValue = inventory.GetSlotValue(activeSlot);
            int itemCount = inventory.GetSlotCount(activeSlot);
            if (!IsHost && itemValue != 0 &&
                BlocksManager.Blocks[Terrain.ExtractContents(itemValue)] is FurnitureBlock)
                m_worldObjectSynchronizer?.PublishLocalFurnitureChangesNow();
            m_localInteractSequence = m_localInteractSequence == int.MaxValue
                ? 1
                : m_localInteractSequence + 1;
            if (TryGetTerrainUsePrediction(player, interactRay.Value,
                    out Point3 terrainUseCell, out int terrainUseExpectedValue))
            {
                m_localTerrainUsePredictions[terrainUseCell] = new LocalTerrainUsePrediction
                {
                    ExpectedValue = terrainUseExpectedValue,
                    LastSeenTime = Time.RealTime
                };
            }
            var request = new PlayerActionMessage(
                PlayerActionType.InteractRequest, client.ClientID, m_localInteractSequence,
                interactRay.Value, activeSlot, itemValue, itemCount);
            if (TryGetTerrainPlacePrediction(player, interactRay.Value,
                out Point3 cell, out int expectedValue, out int predictedValue))
            {
                request.HasTerrainPrediction = true;
                request.RequestId = m_localInteractSequence;
                request.Cell = cell;
                request.ExpectedValue = expectedValue;
                request.PredictedValue = predictedValue;
                if (m_pendingTerrainPlacePredictionCells.TryGetValue(cell,
                    out int previousRequestId))
                    RemovePendingTerrainPlacePrediction(previousRequestId);
                m_pendingTerrainPlacePredictions[request.RequestId] =
                    new PendingTerrainPlacePrediction
                    {
                        Request = request,
                        LocalPredictedValue = predictedValue,
                        IsCollapsingBlock = IsCollapsingBlockValue(predictedValue),
                        // Source: Survivalcraft/Game/SubsystemTerrain.cs:
                        // SubsystemTerrain.ChangeCell
                        // Some block behaviors do not perform a local ChangeCell immediately.
                        // SubmitClientTerrainPredictions marks this true only after observing one.
                        HasLocalPrediction = false,
                        LastSendTime = Time.RealTime,
                        SendCount = 1
                    };
                if (m_pendingTerrainPlacePredictions[request.RequestId].IsCollapsingBlock)
                    m_localCollapsingPlacePredictions[cell] = Time.RealTime +
                        LocalCollapsingPredictionLifetime;
                m_pendingTerrainPlacePredictionCells[cell] = request.RequestId;
            }
            NetworkMessageSender.SendPlayerInteractRequest(request);
        }

        // Source: Survivalcraft/Game/SubsystemRakeBlockBehavior.cs:SubsystemRakeBlockBehavior.OnUse
        // Source: Survivalcraft/Game/SubsystemTrapdoorBlockBehavior.cs:SubsystemTrapdoorBlockBehavior.OnInteract
        private static bool TryGetTerrainUsePrediction(ComponentPlayer player, Ray3 ray,
            out Point3 cell, out int expectedValue)
        {
            cell = default;
            expectedValue = 0;
            ComponentMiner miner = player?.ComponentMiner;
            IInventory inventory = miner?.Inventory;
            if (miner == null)
                return false;
            TerrainRaycastResult? hit = miner.Raycast<TerrainRaycastResult>(
                ray, RaycastMode.Interaction);
            if (!hit.HasValue)
                return false;
            cell = new Point3(hit.Value.CellFace.X, hit.Value.CellFace.Y,
                hit.Value.CellFace.Z);
            expectedValue = Terrain.ReplaceLight(hit.Value.Value, 0);
            if (BlocksManager.Blocks[Terrain.ExtractContents(hit.Value.Value)] is TrapdoorBlock)
                return true;
            if (inventory == null || inventory.ActiveSlotIndex < 0 ||
                inventory.ActiveSlotIndex >= inventory.SlotsCount ||
                hit.Value.CellFace.Face != 4)
                return false;
            int toolValue = inventory.GetSlotValue(inventory.ActiveSlotIndex);
            if (toolValue == 0 || !(BlocksManager.Blocks[Terrain.ExtractContents(toolValue)]
                is RakeBlock))
                return false;
            int targetContents = Terrain.ExtractContents(hit.Value.Value);
            if (targetContents != 2 && targetContents != 8)
                return false;
            return true;
        }

        // Source: Survivalcraft/Game/SubsystemCollapsingBlockBehavior.cs:
        // SubsystemCollapsingBlockBehavior.HandledBlocks
        private static bool IsCollapsingBlockValue(int value)
        {
            int contents = Terrain.ExtractContents(value);
            return contents == 6 || contents == 7;
        }

        // Source: Survivalcraft/Game/SubsystemMovingBlocks.cs:
        // SubsystemMovingBlocks.RemoveMovingBlockSet
        internal void ReconcileAuthoritativeCollapsingCell(Point3 point, int networkValue)
        {
            if (IsHost || !IsCollapsingBlockValue(networkValue)) return;
            SubsystemMovingBlocks moving = GameManager.Project?.FindSubsystem<SubsystemMovingBlocks>(false);
            if (moving == null) return;
            int contents = Terrain.ExtractContents(networkValue);
            foreach (IMovingBlockSet set in moving.MovingBlockSets.ToArray())
            {
                if (set == null || set.Id != "CollapsingBlock") continue;
                Point3 origin = Terrain.ToCell(MathUtils.Round(set.Position.X),
                    MathUtils.Round(set.Position.Y), MathUtils.Round(set.Position.Z));
                if (origin.X != point.X || origin.Z != point.Z ||
                    !set.Blocks.Any(block => Terrain.ExtractContents(block.Value) == contents))
                    continue;
                // The host's final cell is authoritative. Removing the local set prevents its
                // stopped callback from writing a second, stale landing value.
                moving.RemoveMovingBlockSet(set);
            }
        }

        // Source: Survivalcraft/Game/SubsystemCollapsingBlockBehavior.cs:
        // SubsystemCollapsingBlockBehavior.MovingBlocksStopped
        private void RemoveLocalCollapsingSets(Point3 column,
            Dictionary<Point3, bool> repairCells)
        {
            SubsystemMovingBlocks moving = GameManager.Project?.FindSubsystem<SubsystemMovingBlocks>(false);
            if (moving == null) return;
            foreach (IMovingBlockSet set in moving.MovingBlockSets.ToArray())
            {
                if (set == null || set.Id != "CollapsingBlock") continue;
                Point3 origin = Terrain.ToCell(MathUtils.Round(set.Position.X),
                    MathUtils.Round(set.Position.Y), MathUtils.Round(set.Position.Z));
                if (origin.X != column.X || origin.Z != column.Z) continue;
                if (repairCells != null)
                {
                    repairCells[column] = true;
                    foreach (MovingBlock block in set.Blocks)
                        repairCells[origin + block.Offset] = true;
                }
                moving.RemoveMovingBlockSet(set);
            }
        }

        // Source: Survivalcraft/Game/ComponentMiner.cs:ComponentMiner.Place
        private static bool TryGetTerrainPlacePrediction(ComponentPlayer player, Ray3 ray,
            out Point3 cell, out int expectedValue, out int predictedValue)
        {
            cell = default;
            expectedValue = 0;
            predictedValue = 0;
            ComponentMiner miner = player?.ComponentMiner;
            IInventory inventory = miner?.Inventory;
            SubsystemTerrain terrain = GameManager.Project?.FindSubsystem<SubsystemTerrain>(false);
            if (miner == null || inventory == null || terrain == null)
                return false;
            int activeSlot = inventory.ActiveSlotIndex;
            if (activeSlot < 0 || activeSlot >= inventory.SlotsCount)
                return false;
            int itemValue = inventory.GetSlotValue(activeSlot);
            if (itemValue == 0 || inventory.GetSlotCount(activeSlot) <= 0)
                return false;
            Block block = BlocksManager.Blocks[Terrain.ExtractContents(itemValue)];
            if (!block.IsPlaceable) return false;
            TerrainRaycastResult? hit = miner.Raycast<TerrainRaycastResult>(
                ray, RaycastMode.Interaction);
            if (!hit.HasValue) return false;
            BlockPlacementData placement = block.GetPlacementValue(
                terrain, miner, itemValue, hit.Value);
            if (placement.Value == 0) return false;
            Point3 offset = CellFace.FaceToPoint3(placement.CellFace.Face);
            cell = new Point3(placement.CellFace.X + offset.X,
                placement.CellFace.Y + offset.Y, placement.CellFace.Z + offset.Z);
            if (!terrain.Terrain.IsCellValid(cell.X, cell.Y, cell.Z)) return false;
            expectedValue = Terrain.ReplaceLight(
                terrain.Terrain.GetCellValue(cell.X, cell.Y, cell.Z), 0);
            predictedValue = Terrain.ReplaceLight(placement.Value, 0);
            return predictedValue != 0;
        }

        // Source: Survivalcraft/Game/ComponentPlayer.cs:ComponentPlayer.Update
        // Drop is a one-frame edge. Send the pre-prediction slot reliably so a later empty
        // inventory snapshot cannot erase the item before the host executes the native action.
        private void UpdateLocalDropRequests(ComponentPlayer player, bool drop)
        {
            if (!drop || client?.IsConnected != true ||
                player?.ComponentMiner?.Inventory == null || player.ComponentBody == null)
                return;
            IInventory inventory = player.ComponentMiner.Inventory;
            int activeSlot = inventory.ActiveSlotIndex;
            if (activeSlot < 0 || activeSlot >= inventory.SlotsCount) return;
            int itemValue = inventory.GetSlotValue(activeSlot);
            int itemCount = inventory.GetSlotCount(activeSlot);
            if (itemValue == 0 || itemCount <= 0) return;

            m_localDropSequence = m_localDropSequence == int.MaxValue
                ? 1
                : m_localDropSequence + 1;
            var message = new PlayerActionMessage(
                PlayerActionType.DropRequest, client.ClientID, m_localDropSequence,
                default, activeSlot, itemValue, itemCount)
            {
                DropCount = itemCount,
                RemoveCount = itemCount,
                RequestId = m_localEquipmentRevision,
                Position = player.ComponentBody.Position +
                    new Vector3(0f, player.ComponentBody.StanceBoxSize.Y * 0.66f, 0f) +
                    0.25f * player.ComponentBody.Matrix.Forward,
                Velocity = 8f * Matrix.CreateFromQuaternion(
                    player.ComponentCreatureModel.EyeRotation).Forward
            };
            NetworkMessageSender.SendPlayerDropRequest(message);
            m_pendingLocalDropValue = itemValue;
            m_pendingLocalDropCount = itemCount;
            m_pendingLocalDropPosition = message.Position;
            m_pendingLocalDropPredictionUntil = Time.RealTime + 0.5;
        }

