        private static bool IsCockedMusketValue(int value)
        {
            if (value == 0) return false;
            return BlocksManager.Blocks[Terrain.ExtractContents(value)] is MusketBlock &&
                MusketBlock.GetHammerState(Terrain.ExtractData(value));
        }

